import java.util.*;  // imports every class of java.util

public class CollectionMethodsDemo {               // class that holds the main method
    public static void main(String[] args) {       // program entry point
        Collection<String> c = new ArrayList<>();  // creates an empty ArrayList named c

        // add elements
        c.add("Raigad");                         // adds "Raigad" to the end of the list
        c.add("Torna");                          // adds "Torna" to the end of the list
        c.add("Lohagad");                        // adds "Lohagad" to the end of the list
        System.out.println("Collection: " + c);  // prints a label followed by the value

        // contains
        System.out.println("Contains Raigad? " + c.contains("Raigad"));  // prints whether the element is present

        // size and isEmpty
        System.out.println("Size: " + c.size());         // prints the number of elements
        System.out.println("Is Empty? " + c.isEmpty());  // prints whether it is empty

        // remove
        c.remove("Lohagad");                       // removes "Lohagad" from the collection
        System.out.println("After remove: " + c);  // prints a label followed by the value

        // toArray
        Object[] arr = c.toArray();                         // stores the result: copies the elements into an array
        System.out.println("Array length: " + arr.length);  // prints a label followed by the value

        // iterator
        Iterator<String> it = c.iterator();               // stores the result: gets an iterator to walk the elements
        while (it.hasNext()) {                            // runs while the iterator has more elements
            System.out.println("Element: " + it.next());  // prints the next element
        }

        // clear
        c.clear();  // removes every element from the collection
        System.out.println("After clear, isEmpty: " + c.isEmpty());  // prints whether it is empty
    }
}

import java.util.*;  // imports every class of java.util

public class QueueDemo {                           // class that holds the main method
    public static void main(String[] args) {       // program entry point
        Queue<String> queue = new LinkedList<>();  // creates an empty LinkedList named queue

        // Insert - offer() is preferred (doesn't throw on failure)
        queue.offer("Task1");                   // adds "Task1" at the tail without throwing if the queue is full
        queue.offer("Task2");                   // adds "Task2" at the tail without throwing if the queue is full
        queue.offer("Task3");                   // adds "Task3" at the tail without throwing if the queue is full
        System.out.println("Queue: " + queue);  // prints a label followed by the value

        // Examine head without removing
        System.out.println("Peek: " + queue.peek());  // Task1

        // Remove and process in FIFO order
        System.out.println("Poll: " + queue.poll());  // Task1
        System.out.println("After poll: " + queue);   // [Task2, Task3]

        // PriorityQueue - orders by natural ordering, not insertion order
        Queue<Integer> pq = new PriorityQueue<>();  // creates an empty PriorityQueue named pq
        pq.offer(30);                               // adds 30 at the tail without throwing if the queue is full
        pq.offer(10);                               // adds 10 at the tail without throwing if the queue is full
        pq.offer(20);                               // adds 20 at the tail without throwing if the queue is full
        System.out.println("PriorityQueue poll order: " + pq.poll() + ", " + pq.poll() + ", " + pq.poll());  // prints the removed element
        // 10, 20, 30 - smallest first, regardless of insertion order
    }
}

