class Lru<K, V> extends LinkedHashMap<K, V> {                 // Lru class extending LinkedHashMap<K, V>
    private final int cap;                                    // field cap of type int
    Lru(int cap) {                                            // constructor
        super(16, 0.75f, true);                               // calls the parent class constructor
        this.cap = cap;                                       // stores cap in the field cap
    }
    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> e) {  // method removeEldestEntry()
        return size() > cap;                                  // returns the result to the caller
    }
}
