// ArrayList constructors: empty, with capacity, and copy of another collection
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class ArrayListCreateDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1) Empty list: the usual way; the type goes on the left, the diamond <> infers it on the right
        List<String> forts = new ArrayList<>();  // creates an empty ArrayList named forts
        forts.add("Raigad");                     // adds "Raigad" to the end of the list
        forts.add("Sinhagad");                   // adds "Sinhagad" to the end of the list
        System.out.println("Empty list then two adds: " + forts);  // prints a label followed by the value

        // 2) Capacity hint: still empty (size 0), but ready to hold 100 elements without growing
        List<String> manyCities = new ArrayList<>(100);  // creates an ArrayList with initial capacity 100
        System.out.println("With capacity 100, size is: " + manyCities.size());  // prints the number of elements

        // 3) Copy constructor: builds a NEW list holding the same elements
        List<String> copy = new ArrayList<>(forts);  // creates an ArrayList named copy copied from forts
        copy.add("Torna");                           // adds "Torna" to the end of the list
        System.out.println("Copy after adding Torna : " + copy);  // prints a label followed by the value
        System.out.println("Original is unchanged   : " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// Empty list then two adds: [Raigad, Sinhagad]
// With capacity 100, size is: 0
// Copy after adding Torna : [Raigad, Sinhagad, Torna]
// Original is unchanged   : [Raigad, Sinhagad]

