// ArrayList with numbers: wrapper types and autoboxing
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class ArrayListNumbersDemo {           // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // List<int> is NOT allowed. Use List<Integer>.
        List<Integer> trekHours = new ArrayList<>();  // creates an empty ArrayList named trekHours

        trekHours.add(4);  // the int 4 is autoboxed to an Integer object
        trekHours.add(2);  // adds 2 to the end of the list
        trekHours.add(6);  // adds 6 to the end of the list

        int first = trekHours.get(0);  // unboxed back to a plain int
        int total = 0;                 // declares int total with value 0
        for (int hours : trekHours) {  // each Integer is unboxed in the loop
            total += hours;            // updates total
        }

        System.out.println("Trek hours: " + trekHours);  // prints a label followed by the value
        System.out.println("First     : " + first);      // prints a label followed by the value
        System.out.println("Total     : " + total);      // prints a label followed by the value
    }
}
// OUTPUT:
// Trek hours: [4, 2, 6]
// First     : 4
// Total     : 12

