// ArrayList add(int index, E e): inserts at a position
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class ArrayListAddAtIndexDemo {                    // class that holds the main method
    public static void main(String[] args) {              // program entry point
        List<String> cities = new ArrayList<>(List.of("Pune", "Nashik", "Nagpur"));  // creates an ArrayList filled with the listed values
        System.out.println("Before        : " + cities);  // prints a label followed by the value

        cities.add(1, "Mumbai");                          // goes to index 1; Nashik and Nagpur shift right
        cities.add(0, "Delhi");                           // insert at the very front
        cities.add(cities.size(), "Jaipur");              // index == size() means "at the end"
        System.out.println("After inserts : " + cities);  // prints a label followed by the value

        try {                                    // code that may throw an exception
            cities.add(10, "Kochi");             // 10 is beyond size(): not allowed
        } catch (IndexOutOfBoundsException e) {  // handles IndexOutOfBoundsException
            System.out.println("Error         : " + e.getMessage());  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// Before        : [Pune, Nashik, Nagpur]
// After inserts : [Delhi, Pune, Mumbai, Nashik, Nagpur, Jaipur]
// Error         : Index: 10, Size: 6

// ArrayList addAll(Collection c): adds a whole collection at the end
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class
import java.util.Set;        // imports the Set class
import java.util.TreeSet;    // imports the TreeSet class

public class ArrayListAddAllDemo {                              // class that holds the main method
    public static void main(String[] args) {                    // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Sinhagad"));  // creates an ArrayList filled with the listed values
        List<String> moreForts = List.of("Torna", "Purandar");  // moreForts is an immutable list of the listed values
        Set<String> sortedForts = new TreeSet<>(List.of("Rajgad", "Lohagad"));  // a Set works too

        boolean changed = forts.addAll(moreForts);           // stores the result: adds every element of moreForts to the list
        System.out.println("addAll returned : " + changed);  // prints a label followed by the value
        System.out.println("After list      : " + forts);    // prints a label followed by the value

        forts.addAll(sortedForts);                         // a TreeSet hands over its elements in sorted order
        System.out.println("After set       : " + forts);  // prints a label followed by the value

        boolean empty = forts.addAll(List.of());           // nothing to add
        System.out.println("Adding empty    : " + empty);  // prints a label followed by the value
    }
}
// OUTPUT:
// addAll returned : true
// After list      : [Raigad, Sinhagad, Torna, Purandar]
// After set       : [Raigad, Sinhagad, Torna, Purandar, Lohagad, Rajgad]
// Adding empty    : false

