// ArrayList contains(Object o): is the value present?
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class ArrayListContainsDemo {          // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Sinhagad", "Pratapgad"));  // creates an ArrayList filled with the listed values

        System.out.println("Contains Raigad?   " + forts.contains("Raigad"));  // prints whether the element is present
        System.out.println("Contains Torna?    " + forts.contains("Torna"));  // prints whether the element is present
        System.out.println("Case matters:      " + forts.contains("raigad"));  // equals() is case-sensitive

        if (!forts.contains("Torna")) {                     // a common guard before adding, to avoid duplicates
            forts.add("Torna");                             // adds "Torna" to the end of the list
        }
        System.out.println("After guard add:   " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// Contains Raigad?   true
// Contains Torna?    false
// Case matters:      false
// After guard add:   [Raigad, Sinhagad, Pratapgad, Torna]

