        List<String> forts = new ArrayList<>(List.of("Torna", "Raigad", "Sinhagad", "Lohagad"));  // creates an ArrayList filled with the listed values

        forts.sort(null);                                 // natural order: alphabetical
        System.out.println("Natural        : " + forts);  // prints a label followed by the value

        forts.sort(Comparator.reverseOrder());            // Z to A
        System.out.println("Reverse        : " + forts);  // prints a label followed by the value

        forts.sort(Comparator.comparing(String::length));  // shortest name first (stable for equal lengths)
        System.out.println("By length      : " + forts);   // prints a label followed by the value

        Collections.sort(forts);                          // the older style, same result as sort(null)
        System.out.println("Collections    : " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// Natural        : [Lohagad, Raigad, Sinhagad, Torna]
// Reverse        : [Torna, Sinhagad, Raigad, Lohagad]
// By length      : [Torna, Raigad, Lohagad, Sinhagad]
// Collections    : [Lohagad, Raigad, Sinhagad, Torna]

// Collections.reverse / swap / shuffle on an ArrayList
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class
import java.util.Random;       // imports the Random class

public class ArrayListReorderDemo {           // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> cities = new ArrayList<>(List.of("Pune", "Nashik", "Nagpur", "Indore"));  // creates an ArrayList filled with the listed values

        Collections.reverse(cities);                // reverses the order of the elements
        System.out.println("reverse : " + cities);  // prints a label followed by the value

        Collections.swap(cities, 0, 3);             // exchange the first and the last
