// ArrayList remove(int index) and remove(Object o)
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class ArrayListRemoveDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna", "Sinhagad"));  // creates an ArrayList filled with the listed values

        String gone = forts.remove(0);  // by index: returns the removed element
        System.out.println("remove(0)          : " + gone + " -> " + forts);  // prints a label followed by the value

        boolean removed = forts.remove("Sinhagad");  // by value: removes only the FIRST match
        System.out.println("remove(\"Sinhagad\") : " + removed + " -> " + forts);  // prints the result

        boolean missing = forts.remove("Panhala");  // not present: false, list unchanged
        System.out.println("remove(\"Panhala\")  : " + missing + " -> " + forts);  // prints the result

        // The Integer trap: an int argument means "index", an Integer object means "value"
        List<Integer> numbers = new ArrayList<>(List.of(10, 20, 30, 2));  // creates an ArrayList filled with the listed values
        numbers.remove(2);                                      // index 2 -> removes 30, NOT the value 2
        System.out.println("remove(2) on ints  : " + numbers);  // prints a label followed by the value
        numbers.remove(Integer.valueOf(2));                     // value 2
        System.out.println("remove(Integer 2)  : " + numbers);  // prints a label followed by the value
    }
}
// OUTPUT:
// remove(0)          : Raigad -> [Sinhagad, Torna, Sinhagad]
// remove("Sinhagad") : true -> [Torna, Sinhagad]
// remove("Panhala")  : false -> [Torna, Sinhagad]
// remove(2) on ints  : [10, 20, 2]
// remove(Integer 2)  : [10, 20]

