// ArrayList stream(): filter, transform and collect without loops
import java.util.ArrayList;          // imports the ArrayList class
import java.util.List;               // imports the List class
import java.util.stream.Collectors;  // imports the Collectors class

public class ArrayListStreamDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Sinhagad", "Pratapgad", "Torna", "Purandar"));  // creates an ArrayList filled with the listed values

        List<String> longNames = forts.stream()
                .filter(name -> name.length() > 6)        // keep long names
                .map(String::toUpperCase)                 // transform each one
                .collect(Collectors.toList());            // collect into a new list
        System.out.println("Long names : " + longNames);  // prints a label followed by the value

        long count = forts.stream().filter(name -> name.startsWith("P")).count();  // stores the result: creates a stream of the elements
        System.out.println("Start with P: " + count);  // prints a label followed by the value

        String joined = forts.stream().collect(Collectors.joining(" | "));  // stores the result: creates a stream of the elements
        System.out.println("Joined     : " + joined);  // prints a label followed by the value
        System.out.println("Original   : " + forts);   // unchanged
    }
}
// OUTPUT:
// Long names : [SINHAGAD, PRATAPGAD, PURANDAR]
// Start with P: 2
// Joined     : Raigad | Sinhagad | Pratapgad | Torna | Purandar
// Original   : [Raigad, Sinhagad, Pratapgad, Torna, Purandar]

// List.of / List.copyOf / Arrays.asList versus a real ArrayList
import java.util.ArrayList;  // imports the ArrayList class
import java.util.Arrays;     // imports the Arrays class
import java.util.List;       // imports the List class

public class ArrayListFactoryDemo {                           // class that holds the main method
    public static void main(String[] args) {                  // program entry point
        List<String> immutable = List.of("Raigad", "Torna");  // immutable is an immutable list of the listed values
        List<String> fixedSize = Arrays.asList("Raigad", "Torna");  // fixedSize wraps the values as a fixed-size list
        List<String> mutable = new ArrayList<>(immutable);    // a real, growable copy

        try {                                        // code that may throw an exception
            immutable.add("Purandar");               // adds "Purandar" to the end of the list
        } catch (UnsupportedOperationException e) {  // handles UnsupportedOperationException
            System.out.println("List.of      : add is not supported");  // prints the text "List.of      : add is not s..."
        }

        fixedSize.set(0, "Rajgad");                  // set is allowed on asList
        System.out.println("Arrays.asList: set worked -> " + fixedSize);  // prints a label followed by the value
        try {                                        // code that may throw an exception
            fixedSize.add("Purandar");               // but size cannot change
        } catch (UnsupportedOperationException e) {  // handles UnsupportedOperationException
            System.out.println("Arrays.asList: add is not supported");  // prints the text "Arrays.asList: add is not s..."
        }

        mutable.add("Purandar");                           // adds "Purandar" to the end of the list
        System.out.println("new ArrayList : " + mutable);  // prints a label followed by the value
    }
}
// OUTPUT:
// List.of      : add is not supported
// Arrays.asList: set worked -> [Rajgad, Torna]
// Arrays.asList: add is not supported
// new ArrayList : [Raigad, Torna, Purandar]

// Collections.unmodifiableList / synchronizedList: wrapper views
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class

public class ArrayListWrappersDemo {          // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Torna"));  // creates an ArrayList filled with the listed values

        List<String> readOnly = Collections.unmodifiableList(forts);  // stores the value in readOnly
        try {                                                   // code that may throw an exception
            readOnly.add("Purandar");                           // adds "Purandar" to the end of the list
        } catch (UnsupportedOperationException e) {             // handles UnsupportedOperationException
            System.out.println("Read-only view blocks add()");  // prints the text "Read-only view blocks add()"
        }

        forts.add("Lohagad");                                  // change through the ORIGINAL list
        System.out.println("The view sees it : " + readOnly);  // prints a label followed by the value

        List<String> safe = Collections.synchronizedList(new ArrayList<>(forts));  // stores the value in safe
        synchronized (safe) {           // required while iterating a synchronized list
            for (String name : safe) {  // loops over every element of safe
                System.out.println("Safe loop        : " + name);  // prints a label followed by the value
            }
        }
    }
}
// OUTPUT:
// Read-only view blocks add()
// The view sees it : [Raigad, Torna, Lohagad]
// Safe loop        : Raigad
// Safe loop        : Torna
// Safe loop        : Lohagad

// ArrayList clone() and copy constructor: shallow copies
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class ArrayListCloneDemo {                            // class that holds the main method
    public static void main(String[] args) {                 // program entry point
        ArrayList<StringBuilder> forts = new ArrayList<>();  // creates an empty ArrayList named forts
        forts.add(new StringBuilder("Raigad"));              // adds new StringBuilder("Raigad") to the end of the list
        forts.add(new StringBuilder("Torna"));               // adds new StringBuilder("Torna") to the end of the list

        @SuppressWarnings("unchecked")
        ArrayList<StringBuilder> viaClone = (ArrayList<StringBuilder>) forts.clone();  // stores the result: creates a shallow copy
        List<StringBuilder> viaConstructor = new ArrayList<>(forts);  // creates an ArrayList named viaConstructor copied from forts

        forts.add(new StringBuilder("Purandar"));  // structure change: copies are NOT affected
        System.out.println("Original size   : " + forts.size());  // prints the number of elements
        System.out.println("Clone size      : " + viaClone.size());  // prints the number of elements
        System.out.println("Constructor size: " + viaConstructor.size());  // prints the number of elements

        forts.get(0).append(" (fort)");  // but the element object is SHARED
        System.out.println("Clone element   : " + viaClone.get(0));  // prints the element or value read
        System.out.println("Same object?    : " + (forts.get(0) == viaClone.get(0)));  // prints the element or value read
    }
}
// OUTPUT:
// Original size   : 3
// Clone size      : 2
// Constructor size: 2
// Clone element   : Raigad (fort)
// Same object?    : true

// ArrayList equals / hashCode / toString
import java.util.ArrayList;   // imports the ArrayList class
import java.util.LinkedList;  // imports the LinkedList class
import java.util.List;        // imports the List class

public class ArrayListEqualsDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> a = new ArrayList<>(List.of("Raigad", "Torna"));  // creates an ArrayList filled with the listed values
        List<String> b = new ArrayList<>(List.of("Raigad", "Torna"));  // creates an ArrayList filled with the listed values
        List<String> c = new ArrayList<>(List.of("Torna", "Raigad"));  // same elements, other order
        List<String> d = new LinkedList<>(List.of("Raigad", "Torna"));  // other List class

        System.out.println("a.equals(b)      : " + a.equals(b));  // prints the comparison result
        System.out.println("a == b           : " + (a == b));  // different objects
        System.out.println("a.equals(c)      : " + a.equals(c));  // order matters
        System.out.println("a.equals(d)      : " + a.equals(d));  // class does not matter
        System.out.println("hash equal       : " + (a.hashCode() == b.hashCode()));  // prints the comparison result
        System.out.println("toString         : " + a);         // prints a label followed by the value
    }
}
// OUTPUT:
// a.equals(b)      : true
// a == b           : false
// a.equals(c)      : false
// a.equals(d)      : true
// hash equal       : true
