// ArrayList iterator(): walk and remove safely
import java.util.ArrayList;  // imports the ArrayList class
import java.util.Iterator;   // imports the Iterator class
import java.util.List;       // imports the List class

public class ArrayListIteratorDemo {          // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> cities = new ArrayList<>(List.of("Pune", "Nashik", "Nagpur", "Indore", "Jaipur"));  // creates an ArrayList filled with the listed values

        Iterator<String> it = cities.iterator();  // stores the result: gets an iterator to walk the elements
        while (it.hasNext()) {                    // is there another element?
            String city = it.next();              // move forward and read it
            if (city.startsWith("N")) {           // checks the condition
                it.remove();                      // the only SAFE way to remove during iteration
            }
        }
        System.out.println(cities);               // prints cities
    }
}
// OUTPUT:
// [Pune, Indore, Jaipur]

// ArrayList listIterator(): forward, backward, set and add
import java.util.ArrayList;     // imports the ArrayList class
import java.util.List;          // imports the List class
import java.util.ListIterator;  // imports the ListIterator class

public class ArrayListListIteratorDemo {      // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna"));  // creates an ArrayList filled with the listed values

        ListIterator<String> it = forts.listIterator();  // stores the result: gets a list iterator that can move in both directions
        while (it.hasNext()) {                           // runs while the iterator has more elements
            String name = it.next();                     // stores the result: moves to and returns the next element
            if (name.equals("Sinhagad")) {               // checks the condition
                it.set("Rajgad");                        // replace the element just returned
                it.add("Purandar");                      // insert right after it
            }
        }
        System.out.println("After set/add : " + forts);  // prints a label followed by the value

        System.out.print("Backwards     : ");         // prints the text "Backwards     : "
        ListIterator<String> back = forts.listIterator(forts.size());  // start at the end
        while (back.hasPrevious()) {                  // runs while there is an earlier element
            System.out.print(back.previous() + " ");  // prints the next element
        }
        System.out.println();                         // prints an empty line
    }
}
// OUTPUT:
// After set/add : [Raigad, Rajgad, Purandar, Torna]
// Backwards     : Torna Purandar Rajgad Raigad

