// ConcurrentModificationException and the three safe fixes
import java.util.ArrayList;                        // imports the ArrayList class
import java.util.ConcurrentModificationException;  // imports the ConcurrentModificationException class
import java.util.Iterator;                         // imports the Iterator class
import java.util.List;                             // imports the List class

public class ArrayListFailFastDemo {          // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna", "Purandar"));  // creates an ArrayList filled with the listed values

        try {                                          // code that may throw an exception
            for (String fort : forts) {                // loops over every element of forts
                if (fort.equals("Sinhagad")) {         // checks the condition
                    forts.remove(fort);                // BAD: structure changed during iteration
                }
            }
        } catch (ConcurrentModificationException e) {  // handles ConcurrentModificationException
            System.out.println("BAD way failed: ConcurrentModificationException");  // prints the text "BAD way failed: ConcurrentM..."
        }

        List<String> a = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna", "Purandar"));  // creates an ArrayList filled with the listed values
        a.removeIf(name -> name.equals("Sinhagad"));   // fix 1: removeIf
        System.out.println("removeIf        : " + a);  // prints a label followed by the value

        List<String> b = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna", "Purandar"));  // creates an ArrayList filled with the listed values
        Iterator<String> it = b.iterator();            // fix 2: Iterator.remove
        while (it.hasNext()) {                         // runs while the iterator has more elements
            if (it.next().equals("Sinhagad")) {        // checks the condition
                it.remove();                           // removes the head element
            }
        }
        System.out.println("Iterator.remove : " + b);  // prints a label followed by the value

        List<String> c = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna", "Purandar"));  // creates an ArrayList filled with the listed values
        for (String name : new ArrayList<>(c)) {       // fix 3: loop over a copy, change the original
            if (name.equals("Sinhagad")) {             // checks the condition
                c.remove(name);                        // removes name from the list
            }
        }
        System.out.println("loop over copy  : " + c);  // prints a label followed by the value
    }
}
// OUTPUT:
// BAD way failed: ConcurrentModificationException
// removeIf        : [Raigad, Torna, Purandar]
// Iterator.remove : [Raigad, Torna, Purandar]
// loop over copy  : [Raigad, Torna, Purandar]

// ArrayList ensureCapacity / trimToSize and how capacity grows
import java.util.ArrayList;  // imports the ArrayList class

public class ArrayListCapacityDemo {                       // class that holds the main method
    public static void main(String[] args) {               // program entry point
        ArrayList<Integer> trekHours = new ArrayList<>();  // creates an empty ArrayList named trekHours
        trekHours.ensureCapacity(1000);                    // room for 1000 elements, but size is still 0
        System.out.println("size after ensureCapacity: " + trekHours.size());  // prints the number of elements

        for (int i = 1; i <= 5; i++) {  // counting loop
            trekHours.add(i);           // adds i to the end of the list
        }
        trekHours.trimToSize();         // drop the unused room (capacity becomes 5)
        System.out.println("size after trimToSize   : " + trekHours.size());  // prints the number of elements

        // The growth rule inside ArrayList: newCapacity = oldCapacity + oldCapacity / 2 (about 1.5 times)
        int capacity = 10;                          // the first add allocates 10
        StringBuilder steps = new StringBuilder("capacity growth: " + capacity);  // creates a StringBuilder object named steps
        for (int i = 0; i < 6; i++) {               // counting loop
            capacity = capacity + (capacity >> 1);  // assigns a new value to capacity
            steps.append(" -> ").append(capacity);  // calls append() on steps
        }
        System.out.println(steps);                  // prints steps
    }
}
// OUTPUT:
// size after ensureCapacity: 0
// size after trimToSize   : 5
// capacity growth: 10 -> 15 -> 22 -> 33 -> 49 -> 73 -> 109

// Why contains() fails for your own class unless equals() is defined
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class ArrayListEqualsTrapDemo {  // class that holds the main method
    static class PlainFort {            // no equals(): identity comparison
        final String name;              // declares name of type String
        PlainFort(String name) {        // constructor
            this.name = name;           // stores name in the field name
        }
    }

    record RecordFort(String name) { }  // equals() and hashCode() are generated from the fields

    public static void main(String[] args) {        // program entry point
        List<PlainFort> plain = new ArrayList<>();  // creates an empty ArrayList named plain
        plain.add(new PlainFort("Raigad"));         // adds new PlainFort("Raigad") to the end of the list
        System.out.println("Plain class contains new PlainFort(Raigad)? " + plain.contains(new PlainFort("Raigad")));  // prints whether the element is present

        List<RecordFort> records = new ArrayList<>();  // creates an empty ArrayList named records
        records.add(new RecordFort("Raigad"));         // adds new RecordFort("Raigad") to the end of the list
        System.out.println("Record contains new RecordFort(Raigad)?     " + records.contains(new RecordFort("Raigad")));  // prints whether the element is present
        System.out.println("indexOf works the same way: " + records.indexOf(new RecordFort("Raigad")));  // prints the index of the element
    }
}
// OUTPUT:
// Plain class contains new PlainFort(Raigad)? false
// Record contains new RecordFort(Raigad)?     true
