// subList view becomes invalid when the parent list changes size
import java.util.ArrayList;                        // imports the ArrayList class
import java.util.ConcurrentModificationException;  // imports the ConcurrentModificationException class
import java.util.List;                             // imports the List class

public class ArrayListSubListTrapDemo {           // class that holds the main method
    public static void main(String[] args) {      // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna", "Purandar"));  // creates an ArrayList filled with the listed values
        List<String> view = forts.subList(0, 2);  // stores the result: takes the view from index 0 (inclusive) to 2 (exclusive)

        forts.add("Lohagad");                          // structural change to the PARENT
        try {                                          // code that may throw an exception
            System.out.println(view.size());           // the view notices and refuses
        } catch (ConcurrentModificationException e) {  // handles ConcurrentModificationException
            System.out.println("Using the view after the parent changed -> ConcurrentModificationException");  // prints the text "Using the view after the pa..."
        }

        List<String> safeCopy = new ArrayList<>(forts.subList(0, 2));  // a real copy never breaks
        forts.add("Panhala");                                // adds "Panhala" to the end of the list
        System.out.println("Copy still fine: " + safeCopy);  // prints a label followed by the value
    }
}
// OUTPUT:
// Using the view after the parent changed -> ConcurrentModificationException
// Copy still fine: [Raigad, Sinhagad]

// CopyOnWriteArrayList: loops see a snapshot, so no ConcurrentModificationException
import java.util.ArrayList;                        // imports the ArrayList class
import java.util.List;                             // imports the List class
import java.util.concurrent.CopyOnWriteArrayList;  // imports the CopyOnWriteArrayList class

public class ArrayListThreadSafeDemo {        // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = new CopyOnWriteArrayList<>(List.of("Raigad", "Sinhagad", "Torna"));  // creates a CopyOnWriteArrayList filled with the listed values

        for (String fort : forts) {                         // iterates over a SNAPSHOT of the array
            if (fort.equals("Sinhagad")) {                  // checks the condition
                forts.add("Purandar");                      // allowed: writes go to a fresh copy
            }
        }
        System.out.println("CopyOnWrite list : " + forts);  // prints a label followed by the value

        List<String> normal = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna"));  // creates an ArrayList filled with the listed values
        try {                                   // code that may throw an exception
            for (String fort : normal) {        // loops over every element of normal
                if (fort.equals("Sinhagad")) {  // checks the condition
                    normal.add("Purandar");     // same code on an ArrayList
                }
            }
        } catch (RuntimeException e) {          // handles RuntimeException
            System.out.println("Plain ArrayList  : " + e.getClass().getSimpleName());  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// CopyOnWrite list : [Raigad, Sinhagad, Torna, Purandar]
// Plain ArrayList  : ConcurrentModificationException

// Route planner: add, insert, remove, sort, search and copy on one ArrayList
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class

public class RoutePlannerDemo {                         // class that holds the main method
    public static void main(String[] args) {            // program entry point
        List<String> route = new ArrayList<>();         // empty route
        route.add("Pune");                              // start
        route.add("Nashik");                            // adds "Nashik" to the end of the list
        route.add("Indore");                            // adds "Indore" to the end of the list
        route.add(1, "Mumbai");                         // insert a stop after the start
        route.addAll(List.of("Jaipur", "Delhi"));       // append two stops together
        System.out.println("Route        : " + route);  // prints a label followed by the value

        route.remove("Indore");                         // cancel one stop by name
        System.out.println("After cancel : " + route);  // prints a label followed by the value

        List<String> alphabetical = new ArrayList<>(route);    // copy before sorting
        Collections.sort(alphabetical);                        // sorts the list (natural order or the given comparator)
        System.out.println("Alphabetical : " + alphabetical);  // prints a label followed by the value
        System.out.println("Original kept: " + route);         // prints a label followed by the value

        String target = "Jaipur";              // stores the text "Jaipur" in target
        int position = route.indexOf(target);  // stores the result: finds the first index of target
        System.out.println(target + " is stop number " + (position + 1) + " of " + route.size());  // prints the number of elements

        route.removeIf(stop -> stop.length() > 5);      // drop the long names
        System.out.println("Short names  : " + route);  // prints a label followed by the value
    }
}
// OUTPUT:
// Route        : [Pune, Mumbai, Nashik, Indore, Jaipur, Delhi]
// After cancel : [Pune, Mumbai, Nashik, Jaipur, Delhi]
// Alphabetical : [Delhi, Jaipur, Mumbai, Nashik, Pune]
// Original kept: [Pune, Mumbai, Nashik, Jaipur, Delhi]
