// LinkedList used as a Queue (FIFO), a Stack (LIFO) and a Deque
import java.util.Deque;       // imports the Deque class
import java.util.LinkedList;  // imports the LinkedList class
import java.util.Queue;       // imports the Queue class

public class LinkedListRolesDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // Queue: first in, first out
        Queue<String> ticketLine = new LinkedList<>();  // creates an empty LinkedList named ticketLine
        ticketLine.offer("Pune");                       // adds "Pune" at the tail without throwing if the queue is full
        ticketLine.offer("Nashik");                     // adds "Nashik" at the tail without throwing if the queue is full
        ticketLine.offer("Nagpur");                     // adds "Nagpur" at the tail without throwing if the queue is full
        System.out.println("Queue serves : " + ticketLine.poll() + ", then " + ticketLine.poll());  // prints the removed element

        // Stack: last in, first out
        Deque<String> plates = new LinkedList<>();  // creates an empty LinkedList named plates
        plates.push("Raigad");                      // pushes "Raigad" on top of the stack
        plates.push("Sinhagad");                    // pushes "Sinhagad" on top of the stack
        plates.push("Torna");                       // pushes "Torna" on top of the stack
        System.out.println("Stack pops   : " + plates.pop() + ", then " + plates.pop());  // prints the removed element

        // Deque: work at both ends
        Deque<String> both = new LinkedList<>();  // creates an empty LinkedList named both
        both.offerFirst("Mumbai");                // adds "Mumbai" at the head
        both.offerLast("Delhi");                  // adds "Delhi" at the tail without throwing if the queue is full
        both.offerFirst("Kochi");                 // adds "Kochi" at the head
        System.out.println("Deque        : " + both + " first=" + both.peekFirst() + " last=" + both.peekLast());  // prints the element or value read
    }
}
// OUTPUT:
// Queue serves : Pune, then Nashik
// Stack pops   : Torna, then Sinhagad
// Deque        : [Kochi, Mumbai, Delhi] first=Kochi last=Delhi

// LinkedList iterator / listIterator / descendingIterator
import java.util.Iterator;      // imports the Iterator class
import java.util.LinkedList;    // imports the LinkedList class
import java.util.List;          // imports the List class
import java.util.ListIterator;  // imports the ListIterator class

public class LinkedListIteratorDemo {         // class that holds the main method
    public static void main(String[] args) {  // program entry point
        LinkedList<String> forts = new LinkedList<>(List.of("Raigad", "Sinhagad", "Torna", "Purandar"));  // creates a LinkedList filled with the listed values

        Iterator<String> back = forts.descendingIterator();  // last to first
        System.out.print("Backwards : ");                    // prints the text "Backwards : "
        while (back.hasNext()) {                             // runs while the iterator has more elements
            System.out.print(back.next() + " ");             // prints the next element
        }
        System.out.println();                                // prints an empty line

        ListIterator<String> it = forts.listIterator();  // stores the result: gets a list iterator that can move in both directions
        while (it.hasNext()) {                           // runs while the iterator has more elements
            String name = it.next();                     // stores the result: moves to and returns the next element
            if (name.equals("Torna")) {                  // checks the condition
                it.add("Lohagad");                       // O(1) insert right at the cursor
            }
            if (name.equals("Raigad")) {                 // checks the condition
                it.remove();                             // O(1) remove at the cursor
            }
        }
        System.out.println("After edits: " + forts);     // prints a label followed by the value
    }
}
// OUTPUT:
// Backwards : Purandar Torna Sinhagad Raigad
// After edits: [Sinhagad, Torna, Lohagad, Purandar]

