// Why get(i) in a loop is slow on a LinkedList: counting node visits
public class LinkedListQuadraticDemo {  // class that holds the main method
    // A tiny stand-in that counts how many nodes would be walked, using the same "nearest end" rule as LinkedList.node(index)
    static long stepsForGet(int index, int size) {  // method stepsForGet()
        return index < (size >> 1) ? index : (size - 1 - index);  // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        int size = 10_000;                    // declares int size with value 10_000

        long indexedLoopSteps = 0;                     // for (i) list.get(i)
        for (int i = 0; i < size; i++) {               // counting loop
            indexedLoopSteps += stepsForGet(i, size);  // updates indexedLoopSteps
        }
        long iteratorSteps = size;                     // for-each: one step per element

        System.out.println("Elements                  : " + size);  // prints a label followed by the value
        System.out.println("Node visits, index loop   : " + indexedLoopSteps);  // prints a label followed by the value
        System.out.println("Node visits, for-each loop: " + iteratorSteps);  // prints a label followed by the value
        System.out.println("Index loop does about " + (indexedLoopSteps / iteratorSteps) + " times more work");  // prints a label followed by the value
    }
}
// OUTPUT:
// Elements                  : 10000
// Node visits, index loop   : 24995000
// Node visits, for-each loop: 10000
// Index loop does about 2499 times more work

// Ticket counter: a Queue for the waiting line and a Deque used as a Stack for undo
import java.util.Deque;       // imports the Deque class
import java.util.LinkedList;  // imports the LinkedList class
import java.util.Queue;       // imports the Queue class

public class TicketCounterDemo {                  // class that holds the main method
    public static void main(String[] args) {      // program entry point
        Queue<String> line = new LinkedList<>();  // first come, first served
        line.offer("Pune");                       // adds "Pune" at the tail without throwing if the queue is full
        line.offer("Nashik");                     // adds "Nashik" at the tail without throwing if the queue is full
        line.offer("Nagpur");                     // adds "Nagpur" at the tail without throwing if the queue is full
        line.offer("Indore");                     // adds "Indore" at the tail without throwing if the queue is full

        Deque<String> served = new LinkedList<>();     // history, most recent on top
        while (line.size() > 1) {                      // repeats while the condition is true
            String city = line.poll();                 // next traveller
            served.push(city);                         // remember who was served
            System.out.println("Served   : " + city);  // prints a label followed by the value
        }

        System.out.println("Waiting  : " + line);    // prints a label followed by the value
        String undone = served.pop();                // undo the most recent service
        line.offer(undone);                          // that traveller goes back to the line
        System.out.println("Undo     : " + undone + " goes back");  // prints a label followed by the value
        System.out.println("Waiting  : " + line);    // prints a label followed by the value
        System.out.println("History  : " + served);  // prints a label followed by the value
    }
}
// OUTPUT:
// Served   : Pune
// Served   : Nashik
// Served   : Nagpur
// Waiting  : [Indore]
// Undo     : Nagpur goes back
// Waiting  : [Indore, Nagpur]
// History  : [Nashik, Pune]

