// Vector capacity management
import java.util.Vector;  // imports the Vector class

public class VectorCapacityDemo {               // class that holds the main method
    public static void main(String[] args) {    // program entry point
        Vector<String> forts = new Vector<>();  // capacity 10
        System.out.println("start            : size " + forts.size() + ", capacity " + forts.capacity());  // prints the number of elements

        for (int i = 1; i <= 11; i++) {  // counting loop
            forts.add("fort" + i);       // the 11th add makes it grow
        }
        System.out.println("after 11 adds    : size " + forts.size() + ", capacity " + forts.capacity());  // doubled to 20

        forts.trimToSize();  // shrinks the capacity to the current size
        System.out.println("after trimToSize : size " + forts.size() + ", capacity " + forts.capacity());  // prints the number of elements

        forts.ensureCapacity(50);  // makes sure the capacity is at least 50
        System.out.println("ensureCapacity(50): capacity " + forts.capacity());  // prints a label followed by the value

        forts.setSize(13);                                  // pads with null
        System.out.println("setSize(13)      : " + forts.subList(10, 13));  // prints the selected range
        forts.setSize(3);                                   // truncates
        System.out.println("setSize(3)       : " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// start            : size 0, capacity 10
// after 11 adds    : size 11, capacity 20
// after trimToSize : size 11, capacity 11
// ensureCapacity(50): capacity 50
// setSize(13)      : [fort11, null, null]
// setSize(3)       : [fort1, fort2, fort3]

