// Safe "add if absent" on a shared Vector: lock around the whole check-then-act
import java.util.Vector;  // imports the Vector class

public class VectorCheckThenActDemo {      // class that holds the main method
    static void addIfAbsent(Vector<String> shared, String fort) {  // method addIfAbsent()
        synchronized (shared) {            // the same lock the Vector uses internally
            if (!shared.contains(fort)) {  // check ...
                shared.add(fort);          // ... then act, with no other thread in between
            }
        }
    }

    public static void main(String[] args) {    // program entry point
        Vector<String> forts = new Vector<>();  // creates an empty Vector named forts
        addIfAbsent(forts, "Raigad");           // calls the addIfAbsent() method
        addIfAbsent(forts, "Torna");            // calls the addIfAbsent() method
        addIfAbsent(forts, "Raigad");           // ignored: already there
        System.out.println(forts);              // prints forts
    }
}
// OUTPUT:
// [Raigad, Torna]

