// Stack pop(): remove from the top, and the empty-stack error
import java.util.EmptyStackException;  // imports the EmptyStackException class
import java.util.Stack;                // imports the Stack class

public class StackPopDemo {                   // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Stack<String> forts = new Stack<>();  // creates an empty Stack named forts
        forts.push("Raigad");                 // pushes "Raigad" on top of the stack
        forts.push("Torna");                  // pushes "Torna" on top of the stack

        while (!forts.empty()) {                          // safe loop: stop when empty
            System.out.println("popped " + forts.pop());  // prints the removed element
        }

        try {                              // code that may throw an exception
            forts.pop();                   // nothing left
        } catch (EmptyStackException e) {  // handles EmptyStackException
            System.out.println("pop on an empty stack -> EmptyStackException");  // prints the text "pop on an empty stack -> Em..."
        }
    }
}
// OUTPUT:
// popped Torna
// popped Raigad
// pop on an empty stack -> EmptyStackException

