// Balanced brackets with a Stack
import java.util.Stack;  // imports the Stack class

public class StackBracketsDemo {                            // class that holds the main method
    static boolean isBalanced(String text) {                // method isBalanced()
        Stack<Character> open = new Stack<>();              // creates an empty Stack named open
        for (char c : text.toCharArray()) {                 // loops over every element of text.toCharArray()
            if (c == '(' || c == '[' || c == '{') {         // checks the condition
                open.push(c);                               // remember the opener
            } else if (c == ')' || c == ']' || c == '}') {  // checks the next condition
                if (open.empty()) {                         // checks the condition
                    return false;                           // a closer with nothing open
                }
                char top = open.pop();                      // the most recent opener must match
                boolean ok = (c == ')' && top == '(') || (c == ']' && top == '[') || (c == '}' && top == '{');  // declares boolean ok with value (c == ')' && top ==...
                if (!ok) {                                  // checks the condition
                    return false;                           // returns the result to the caller
                }
            }
        }
        return open.empty();                                // anything still open is an error
    }

    public static void main(String[] args) {                   // program entry point
        System.out.println("{[()]}  -> " + isBalanced("{[()]}"));  // prints a label followed by the value
        System.out.println("{[(])}  -> " + isBalanced("{[(])}"));  // prints a label followed by the value
        System.out.println("((      -> " + isBalanced("(("));  // prints a label followed by the value
        System.out.println("Pune)   -> " + isBalanced("Pune)"));  // prints a label followed by the value
    }
}
// OUTPUT:
// {[()]}  -> true
// {[(])}  -> false
// ((      -> false
// Pune)   -> false

