// Evaluate a postfix expression with a Stack
import java.util.Stack;  // imports the Stack class

public class StackPostfixDemo {                       // class that holds the main method
    static int evaluate(String expression) {          // method evaluate()
        Stack<Integer> numbers = new Stack<>();       // creates an empty Stack named numbers
        for (String token : expression.split(" ")) {  // loops over every element of expression.split(" ")
            switch (token) {                          // chooses a branch by value
                case "+" -> numbers.push(numbers.pop() + numbers.pop());
                case "*" -> numbers.push(numbers.pop() * numbers.pop());
                case "-" -> { int b = numbers.pop(); int a = numbers.pop(); numbers.push(a - b); }  // order matters
                case "/" -> { int b = numbers.pop(); int a = numbers.pop(); numbers.push(a / b); }
                default -> numbers.push(Integer.parseInt(token));  // a number goes on the stack
            }
        }
        return numbers.pop();                         // the single result is left
    }

    public static void main(String[] args) {  // program entry point
        System.out.println("6 2 3 + *   = " + evaluate("6 2 3 + *"));  // prints a label followed by the value
        System.out.println("10 2 8 * + 3 - = " + evaluate("10 2 8 * + 3 -"));  // prints a label followed by the value
        System.out.println("20 4 /      = " + evaluate("20 4 /"));  // prints a label followed by the value
    }
}
// OUTPUT:
// 6 2 3 + *   = 30
// 10 2 8 * + 3 - = 23
// 20 4 /      = 5

// Recursion uses the call stack; an explicit Stack does the same job safely
import java.util.Stack;  // imports the Stack class

public class StackRecursionDemo {                       // class that holds the main method
    static int depthRecursive(int n) {                  // each call waits on the call stack
        return n == 0 ? 0 : 1 + depthRecursive(n - 1);  // returns the result to the caller
    }

    static int depthWithStack(int n) {           // the same counting with our own Stack
        Stack<Integer> pending = new Stack<>();  // creates an empty Stack named pending
        while (n > 0) {                          // repeats while the condition is true
            pending.push(n);                     // pushes n on top of the stack
            n--;                                 // decrements n
        }
        int depth = 0;                           // declares int depth with value 0
        while (!pending.empty()) {               // repeats while the condition is true
            pending.pop();                       // removes the element on top
            depth++;                             // increments depth
        }
        return depth;                            // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        System.out.println("recursive, n=1000     : " + depthRecursive(1000));  // prints a label followed by the value
        System.out.println("explicit stack, n=1000000: " + depthWithStack(1_000_000));  // prints a label followed by the value
        try {                                 // code that may throw an exception
            depthRecursive(10_000_000);       // far too deep for the call stack
        } catch (StackOverflowError e) {      // handles StackOverflowError
            System.out.println("recursive, n=10000000 : StackOverflowError");  // prints the text "recursive, n=10000000 : Sta..."
        }
    }
}
// OUTPUT:
// recursive, n=1000     : 1000
// explicit stack, n=1000000: 1000000
// recursive, n=10000000 : StackOverflowError

