        } catch (UnsupportedOperationException e) {         // handles UnsupportedOperationException
            System.out.println("Set.of is immutable");      // prints the text "Set.of is immutable"
        }
        try {                                               // code that may throw an exception
            Set.of("Raigad", "Raigad");                     // calls of() on Set
        } catch (IllegalArgumentException e) {              // handles IllegalArgumentException
            System.out.println("Set.of rejects duplicates: " + e.getMessage());  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// a.equals(b)   : true
// hash equal    : true
// Set.of is immutable
// Set.of rejects duplicates: duplicate element: Raigad

