// Set algebra with HashSet
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class
import java.util.TreeSet;  // imports the TreeSet class

public class HashSetAlgebraDemo {             // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Set<String> visitedBySchool = new HashSet<>(Set.of("Raigad", "Sinhagad", "Torna"));  // creates a HashSet filled with the listed values
