// Same answer from List.contains and Set.contains; the set does far less work
import java.util.ArrayList;  // imports the ArrayList class
import java.util.HashSet;    // imports the HashSet class
import java.util.List;       // imports the List class
import java.util.Set;        // imports the Set class

public class HashSetLookupDemo {                              // class that holds the main method
    public static void main(String[] args) {                  // program entry point
        List<String> blockedList = new ArrayList<>();         // creates an empty ArrayList named blockedList
        for (int i = 0; i < 1000; i++) {                      // counting loop
            blockedList.add("fort" + i);                      // adds "fort" + i to the end of the list
        }
        Set<String> blockedSet = new HashSet<>(blockedList);  // same data in a set

        int hitsList = 0;                       // declares int hitsList with value 0
        int hitsSet = 0;                        // declares int hitsSet with value 0
        for (int i = 500; i < 1500; i++) {      // 1000 visits, half of them blocked
            String visit = "fort" + i;          // stores the text "fort" + i in visit
            if (blockedList.contains(visit)) {  // may compare up to 1000 elements
                hitsList++;                     // increments hitsList
            }
            if (blockedSet.contains(visit)) {   // jumps straight to one bucket
                hitsSet++;                      // increments hitsSet
            }
        }
        System.out.println("Blocked visits via list: " + hitsList);  // prints a label followed by the value
        System.out.println("Blocked visits via set : " + hitsSet);  // prints a label followed by the value
    }
}
