// HashSet with your own class: equals() AND hashCode() are required
import java.util.HashSet;  // imports the HashSet class
import java.util.Objects;  // imports the Objects class
import java.util.Set;      // imports the Set class

public class HashSetEqualsHashCodeDemo {   // class that holds the main method
    static class BadFort {                 // equals() but NO hashCode()
        final String name;                 // declares name of type String
        BadFort(String name) {             // constructor
            this.name = name;              // stores name in the field name
        }
        @Override
        public boolean equals(Object o) {  // decides when two objects are equal
            return o instanceof BadFort b && b.name.equals(name);  // returns the result to the caller
        }
    }

    static class GoodFort {                // both methods
        final String name;                 // declares name of type String
        GoodFort(String name) {            // constructor
            this.name = name;              // stores name in the field name
        }
        @Override
        public boolean equals(Object o) {  // decides when two objects are equal
            return o instanceof GoodFort g && g.name.equals(name);  // returns the result to the caller
        }
        @Override
        public int hashCode() {            // hash code consistent with equals()
            return Objects.hash(name);     // returns the result to the caller
        }
    }

    record RecordFort(String name) { }  // generated equals() and hashCode()

    public static void main(String[] args) {  // program entry point
        Set<BadFort> bad = new HashSet<>();   // creates an empty HashSet named bad
        bad.add(new BadFort("Raigad"));       // adds new BadFort("Raigad") to the set (a duplicate is ignored)
        bad.add(new BadFort("Raigad"));       // adds new BadFort("Raigad") to the set (a duplicate is ignored)
        System.out.println("Missing hashCode -> size " + bad.size() + ", contains? " + bad.contains(new BadFort("Raigad")));  // prints the number of elements

        Set<GoodFort> good = new HashSet<>();  // creates an empty HashSet named good
        good.add(new GoodFort("Raigad"));      // adds new GoodFort("Raigad") to the set (a duplicate is ignored)
        good.add(new GoodFort("Raigad"));      // adds new GoodFort("Raigad") to the set (a duplicate is ignored)
        System.out.println("Both methods     -> size " + good.size() + ", contains? " + good.contains(new GoodFort("Raigad")));  // prints the number of elements

        Set<RecordFort> records = new HashSet<>();  // creates an empty HashSet named records
        records.add(new RecordFort("Raigad"));      // adds new RecordFort("Raigad") to the set (a duplicate is ignored)
        records.add(new RecordFort("Raigad"));      // adds new RecordFort("Raigad") to the set (a duplicate is ignored)
        System.out.println("Record           -> size " + records.size());  // prints the number of elements
    }
}
// OUTPUT:
// Missing hashCode -> size 2, contains? false
// Both methods     -> size 1, contains? true
// Record           -> size 1

// A mutable element changes its hash code and gets "lost" in the set
import java.util.HashSet;  // imports the HashSet class
import java.util.Objects;  // imports the Objects class
import java.util.Set;      // imports the Set class

public class HashSetMutableTrapDemo {                           // class that holds the main method
    static class Fort {                                         // declares the Fort class
        String name;                                            // NOT final: can change
        Fort(String name) {                                     // constructor
            this.name = name;                                   // stores name in the field name
        }
        @Override
        public boolean equals(Object o) {                       // decides when two objects are equal
            return o instanceof Fort f && f.name.equals(name);  // returns the result to the caller
        }
        @Override
        public int hashCode() {                                 // hash code consistent with equals()
            return Objects.hash(name);                          // returns the result to the caller
        }
        @Override
        public String toString() {                              // text shown when the object is printed
            return name;                                        // returns the result to the caller
        }
    }

    public static void main(String[] args) {  // program entry point
        Set<Fort> forts = new HashSet<>();    // creates an empty HashSet named forts
        Fort raigad = new Fort("Raigad");     // creates a Fort object named raigad
