// Recently visited forts: no repeats, newest last, only the latest 3 kept
import java.util.LinkedHashSet;  // imports the LinkedHashSet class

public class RecentlyVisitedDemo {  // class that holds the main method
    static final int LIMIT = 3;     // stores the value in LIMIT

    static void visit(LinkedHashSet<String> recent, String fort) {  // method visit()
        recent.addLast(fort);         // new fort goes to the end; a repeat moves to the end
        if (recent.size() > LIMIT) {  // checks the condition
            recent.removeFirst();     // drop the oldest visit
        }
    }

    public static void main(String[] args) {                   // program entry point
        LinkedHashSet<String> recent = new LinkedHashSet<>();  // creates an empty LinkedHashSet named recent

        for (String fort : new String[] {"Raigad", "Sinhagad", "Torna", "Raigad", "Purandar", "Lohagad"}) {  // loops over every element of new String[] {"Raigad", "Sinh...
            visit(recent, fort);  // calls the visit() method
            System.out.println("Visited " + fort + " -> " + recent);  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// Visited Raigad -> [Raigad]
// Visited Sinhagad -> [Raigad, Sinhagad]
// Visited Torna -> [Raigad, Sinhagad, Torna]
// Visited Raigad -> [Sinhagad, Torna, Raigad]
// Visited Purandar -> [Torna, Raigad, Purandar]
