// TreeSet iteration is sorted; comparator() reveals the ordering
import java.util.Comparator;  // imports the Comparator class
import java.util.List;        // imports the List class
import java.util.TreeSet;     // imports the TreeSet class

public class TreeSetIterationDemo {           // class that holds the main method
    public static void main(String[] args) {  // program entry point
        TreeSet<String> natural = new TreeSet<>(List.of("Torna", "Raigad", "Sinhagad"));  // creates a TreeSet filled with the listed values
        TreeSet<String> byLength = new TreeSet<>(Comparator.comparing(String::length).thenComparing(Comparator.naturalOrder()));  // creates a TreeSet ordered by the given comparator
        byLength.addAll(natural);             // adds every element of natural to the set

        natural.forEach(f -> System.out.print(f + " "));  // runs the given action for every element
        System.out.println();                             // prints an empty line
        System.out.println("stream upper : " + natural.stream().map(String::toUpperCase).toList());  // prints a label followed by the value

        System.out.println("natural.comparator()  : " + natural.comparator());  // null means natural ordering
        System.out.println("byLength.comparator() is set: " + (byLength.comparator() != null));  // prints a label followed by the value
        System.out.println("byLength order        : " + byLength);  // prints a label followed by the value
    }
}
// OUTPUT:
// Raigad Sinhagad Torna
// stream upper : [RAIGAD, SINHAGAD, TORNA]
// natural.comparator()  : null
// byLength.comparator() is set: true
// byLength order        : [Torna, Raigad, Sinhagad]

// TreeSet with your own class: Comparable, Comparator, and the ClassCastException
import java.util.Comparator;  // imports the Comparator class
import java.util.Set;         // imports the Set class
import java.util.TreeSet;     // imports the TreeSet class

public class TreeSetCustomClassDemo {           // class that holds the main method
    record Fort(String name, int trekHours) implements Comparable<Fort> {  // Fort record implementing Comparable<Fort>
        @Override
        public int compareTo(Fort other) {      // natural ordering: negative, zero or positive
            return name.compareTo(other.name);  // natural order: by name
        }
    }

    static class PlainFort {      // NOT comparable
        final String name;        // declares name of type String
        PlainFort(String name) {  // constructor
            this.name = name;     // stores name in the field name
        }
    }

    public static void main(String[] args) {                   // program entry point
        Set<Fort> byName = new TreeSet<>();                    // creates an empty TreeSet named byName
        byName.add(new Fort("Torna", 4));                      // adds new Fort("Torna", 4) to the set (a duplicate is ignored)
        byName.add(new Fort("Raigad", 6));                     // adds new Fort("Raigad", 6) to the set (a duplicate is ignored)
        byName.add(new Fort("Purandar", 3));                   // adds new Fort("Purandar", 3) to the set (a duplicate is ignored)
        System.out.println("By name (natural)  : " + byName);  // prints a label followed by the value

        Set<Fort> byHours = new TreeSet<>(Comparator.comparingInt(Fort::trekHours));  // creates a TreeSet ordered by the given comparator
        byHours.addAll(byName);                                 // adds every element of byName to the set
        System.out.println("By trek hours      : " + byHours);  // prints a label followed by the value

        try {                             // code that may throw an exception
            new TreeSet<PlainFort>().add(new PlainFort("Raigad"));
        } catch (ClassCastException e) {  // handles ClassCastException
            System.out.println("Not Comparable     : ClassCastException");  // prints the text "Not Comparable     : ClassC..."
        }
    }
}
// OUTPUT:
// By name (natural)  : [Fort[name=Purandar, trekHours=3], Fort[name=Raigad, trekHours=6], Fort[name=Torna, trekHours=4]]
// By trek hours      : [Fort[name=Purandar, trekHours=3], Fort[name=Torna, trekHours=4], Fort[name=Raigad, trekHours=6]]
// Not Comparable     : ClassCastException

// A comparator that ignores a field loses elements
import java.util.Comparator;  // imports the Comparator class
import java.util.List;        // imports the List class
import java.util.Set;         // imports the Set class
import java.util.TreeSet;     // imports the TreeSet class

public class TreeSetComparatorTrapDemo {      // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = List.of("Torna", "Raigad", "Lohag", "Purandar", "Panhala");  // forts is an immutable list of the listed values

        Set<String> lossy = new TreeSet<>(Comparator.comparing(String::length));  // equal length == "duplicate"
        lossy.addAll(forts);  // adds every element of forts to the set
        System.out.println("Length only      : " + lossy + "  (size " + lossy.size() + " of " + forts.size() + ")");  // prints the number of elements

        Set<String> safe = new TreeSet<>(Comparator.comparing(String::length).thenComparing(Comparator.naturalOrder()));  // creates a TreeSet ordered by the given comparator
        safe.addAll(forts);  // adds every element of forts to the set
        System.out.println("With tie-breaker : " + safe + "  (size " + safe.size() + ")");  // prints the number of elements
    }
}
// OUTPUT:
// Length only      : [Torna, Raigad, Panhala, Purandar]  (size 4 of 5)
// With tie-breaker : [Lohag, Torna, Raigad, Panhala, Purandar]  (size 5)

// Nearest departure for a requested time, using ceiling() and floor()
import java.util.List;     // imports the List class
