public class TreeSetNearestSlotDemo {         // class that holds the main method
    public static void main(String[] args) {  // program entry point
        TreeSet<Integer> departures = new TreeSet<>(List.of(6, 9, 12, 15, 18));  // hours of the day

        for (int wanted : new int[] {5, 9, 10, 20}) {     // loops over every element of new int[] {5, 9, 10, 20}
