// HashMap computeIfAbsent(): group values into lists per key
import java.util.ArrayList;  // imports the ArrayList class
import java.util.HashMap;    // imports the HashMap class
import java.util.List;       // imports the List class
import java.util.Map;        // imports the Map class
import java.util.TreeMap;    // imports the TreeMap class

public class HashMapComputeIfAbsentDemo {     // class that holds the main method
    public static void main(String[] args) {  // program entry point
        String[][] forts = {{"Sinhagad", "Pune"}, {"Raigad", "Raigad"}, {"Torna", "Pune"}, {"Lohagad", "Pune"}, {"Panhala", "Kolhapur"}};  // stores the value in forts

        Map<String, List<String>> byDistrict = new HashMap<>();  // creates an empty HashMap named byDistrict
        for (String[] pair : forts) {                   // loops over every element of forts
            byDistrict.computeIfAbsent(pair[1], district -> new ArrayList<>())  // create the list on first use
