// HashMap computeIfPresent(): update only existing keys; null result removes the entry
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class
import java.util.TreeMap;  // imports the TreeMap class

public class HashMapComputeIfPresentDemo {    // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Map<String, Integer> seatsLeft = new HashMap<>(Map.of("Raigad", 2, "Torna", 5));  // creates a HashMap named seatsLeft copied from Map.of("Raigad", 2, "Torn...

        seatsLeft.computeIfPresent("Raigad", (fort, seats) -> seats - 1);  // 2 -> 1
        seatsLeft.computeIfPresent("Panhala", (fort, seats) -> seats - 1);  // missing: ignored
        System.out.println("After one booking : " + new TreeMap<>(seatsLeft));  // prints a label followed by the value

        seatsLeft.computeIfPresent("Raigad", (fort, seats) -> seats == 1 ? null : seats - 1);  // null removes the entry
        System.out.println("Raigad sold out   : " + new TreeMap<>(seatsLeft));  // prints a label followed by the value
    }
}
// OUTPUT:
// After one booking : {Raigad=1, Torna=5}
