// HashMap merge(): count and combine with a method reference
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class
import java.util.TreeMap;  // imports the TreeMap class

public class HashMapMergeDemo {                         // class that holds the main method
    public static void main(String[] args) {            // program entry point
        Map<String, Integer> counts = new HashMap<>();  // creates an empty HashMap named counts
        for (String city : new String[] {"Pune", "Nashik", "Pune", "Nagpur", "Pune", "Nashik"}) {  // loops over every element of new String[] {"Pune", "Nashik...
            counts.merge(city, 1, Integer::sum);        // absent: 1; present: old + 1
        }
        System.out.println("Visit counts : " + new TreeMap<>(counts));  // prints a label followed by the value

        Map<String, Integer> longest = new HashMap<>();   // creates an empty HashMap named longest
        longest.merge("Raigad", 6, Math::max);            // keep the maximum of old and new
        longest.merge("Raigad", 4, Math::max);            // combines the old and new value for the key
        longest.merge("Raigad", 9, Math::max);            // combines the old and new value for the key
        System.out.println("Longest trek : " + longest);  // prints a label followed by the value

        Map<String, String> notes = new HashMap<>();    // creates an empty HashMap named notes
        notes.merge("Torna", "steep", (oldNote, newNote) -> oldNote + ", " + newNote);  // combines the old and new value for the key
        notes.merge("Torna", "windy", (oldNote, newNote) -> oldNote + ", " + newNote);  // combines the old and new value for the key
        System.out.println("Notes        : " + notes);  // prints a label followed by the value
    }
}
// OUTPUT:
// Visit counts : {Nagpur=1, Nashik=2, Pune=3}
// Longest trek : {Raigad=9}
// Notes        : {Torna=steep, windy}

