// Removing entries while iterating a HashMap
import java.util.HashMap;   // imports the HashMap class
import java.util.Iterator;  // imports the Iterator class
import java.util.Map;       // imports the Map class
import java.util.TreeMap;   // imports the TreeMap class

public class HashMapSafeRemoveDemo {          // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Map<String, Integer> a = new HashMap<>(Map.of("Raigad", 6, "Torna", 5, "Purandar", 3, "Lohagad", 2));  // creates a HashMap named a copied from Map.of("Raigad", 6, "Torn...

        try {                                 // code that may throw an exception
            for (String fort : a.keySet()) {  // loops over every element of a.keySet()
                if (a.get(fort) < 4) {        // checks the condition
                    a.remove(fort);           // BAD: structure change during iteration
                }
            }
        } catch (java.util.ConcurrentModificationException e) {  // handles java.util.ConcurrentModificationException
            System.out.println("BAD way : ConcurrentModificationException");  // prints the text "BAD way : ConcurrentModific..."
        }

        Map<String, Integer> b = new HashMap<>(Map.of("Raigad", 6, "Torna", 5, "Purandar", 3, "Lohagad", 2));  // creates a HashMap named b copied from Map.of("Raigad", 6, "Torn...
        Iterator<Map.Entry<String, Integer>> it = b.entrySet().iterator();  // stores the result: gets the set of key-value entries
        while (it.hasNext()) {                                // runs while the iterator has more elements
            if (it.next().getValue() < 4) {                   // checks the condition
                it.remove();                                  // fix 1: iterator
            }
        }
        System.out.println("Iterator: " + new TreeMap<>(b));  // prints a label followed by the value

        Map<String, Integer> c = new HashMap<>(Map.of("Raigad", 6, "Torna", 5, "Purandar", 3, "Lohagad", 2));  // creates a HashMap named c copied from Map.of("Raigad", 6, "Torn...
        c.entrySet().removeIf(entry -> entry.getValue() < 4);  // fix 2: removeIf
        System.out.println("removeIf: " + new TreeMap<>(c));   // prints a label followed by the value
    }
}
// OUTPUT:
// BAD way : ConcurrentModificationException
// Iterator: {Raigad=6, Torna=5}
// removeIf: {Raigad=6, Torna=5}

// HashMap equals / clone: same pairs means equal
import java.util.HashMap;  // imports the HashMap class
