import java.util.TreeMap;  // imports the TreeMap class

public class HashMapEqualsDemo {              // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Map<String, Integer> a = new HashMap<>(Map.of("Pune", 20, "Mumbai", 22));  // creates a HashMap named a copied from Map.of("Pune", 20, "Mumba...
        Map<String, Integer> b = new TreeMap<>(Map.of("Mumbai", 22, "Pune", 20));  // other class, other order
        Map<String, Integer> c = new HashMap<>(Map.of("Pune", 20, "Mumbai", 99));  // creates a HashMap named c copied from Map.of("Pune", 20, "Mumba...

        System.out.println("a.equals(b): " + a.equals(b));  // same pairs
        System.out.println("a.equals(c): " + a.equals(c));  // different value for Mumbai

        @SuppressWarnings("unchecked")
        Map<String, Integer> copy = (HashMap<String, Integer>) ((HashMap<String, Integer>) a).clone();  // stores the value in copy
