// Map.of / Map.entry / Map.ofEntries / Map.copyOf: immutable maps
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class
import java.util.TreeMap;  // imports the TreeMap class

public class HashMapImmutableDemo {           // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Map<String, Integer> small = Map.of("Pune", 20, "Mumbai", 22);  // small is an immutable map of the listed values
        Map<String, Integer> many = Map.ofEntries(
                Map.entry("Delhi", 11), Map.entry("Chennai", 44), Map.entry("Kochi", 484));  // calls entry() on Map

        try {                                           // code that may throw an exception
            small.put("Nagpur", 712);                   // maps key "Nagpur" to value 712
        } catch (UnsupportedOperationException e) {     // handles UnsupportedOperationException
            System.out.println("Map.of is immutable");  // prints the text "Map.of is immutable"
        }
        try {                                           // code that may throw an exception
            Map.of("Pune", 20, "Pune", 2020);           // calls of() on Map
        } catch (IllegalArgumentException e) {          // handles IllegalArgumentException
            System.out.println("Duplicate key rejected: " + e.getMessage());  // prints a label followed by the value
        }

        Map<String, Integer> editable = new HashMap<>(small);  // a modifiable copy
        editable.putAll(many);                                 // copies every entry of many into the map
        System.out.println(new TreeMap<>(editable));           // prints the result
    }
}
// OUTPUT:
// Map.of is immutable
// Duplicate key rejected: duplicate key: Pune
// {Chennai=44, Delhi=11, Kochi=484, Mumbai=22, Pune=20}

// HashMap keys: identity keys, record keys and a mutated key
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class

public class HashMapKeyTrapDemo {  // class that holds the main method
    static class PlainKey {        // no equals / hashCode: identity only
        final String name;         // declares name of type String
        PlainKey(String name) {    // constructor
            this.name = name;      // stores name in the field name
        }
    }

    record RecordKey(String name) { }  // equals / hashCode generated

    static class MutableKey {              // declares the MutableKey class
        String name;                       // declares name of type String
        MutableKey(String name) {          // constructor
            this.name = name;              // stores name in the field name
        }
        @Override
        public boolean equals(Object o) {  // decides when two objects are equal
            return o instanceof MutableKey k && k.name.equals(name);  // returns the result to the caller
        }
        @Override
        public int hashCode() {            // hash code consistent with equals()
            return name.hashCode();        // returns the result to the caller
        }
    }

    public static void main(String[] args) {             // program entry point
        Map<PlainKey, Integer> plain = new HashMap<>();  // creates an empty HashMap named plain
        plain.put(new PlainKey("Raigad"), 6);            // maps key new PlainKey("Raigad") to value 6
        System.out.println("Plain key (new equal key)  : " + plain.get(new PlainKey("Raigad")));  // prints the element or value read

        Map<RecordKey, Integer> records = new HashMap<>();  // creates an empty HashMap named records
        records.put(new RecordKey("Raigad"), 6);            // maps key new RecordKey("Raigad") to value 6
        System.out.println("Record key (new equal key) : " + records.get(new RecordKey("Raigad")));  // prints the element or value read

        Map<MutableKey, Integer> mutable = new HashMap<>();  // creates an empty HashMap named mutable
        MutableKey key = new MutableKey("Raigad");           // creates a MutableKey object named key
        mutable.put(key, 6);                                 // maps key key to value 6
        key.name = "Rajgad";                                 // the hash code changed after insertion
        System.out.println("Mutated key lookup        : " + mutable.get(key));  // prints the element or value read
        System.out.println("Entries still in the map  : " + mutable.size());  // prints the number of elements
    }
}
// OUTPUT:
// Plain key (new equal key)  : null
// Record key (new equal key) : 6
// Mutated key lookup        : null
// Entries still in the map  : 1

// Word frequency with merge(), sorted by count
import java.util.ArrayList;  // imports the ArrayList class
import java.util.HashMap;    // imports the HashMap class
