// A simple cache with computeIfAbsent()
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class

public class HashMapCacheDemo {   // class that holds the main method
    static int calculations = 0;  // stores the value in calculations

    static int slowTrekHours(String fort) {  // pretend this is an expensive calculation
        calculations++;                      // increments calculations
        return fort.length();                // returns the result to the caller
    }

    public static void main(String[] args) {           // program entry point
        Map<String, Integer> cache = new HashMap<>();  // creates an empty HashMap named cache

        for (String fort : new String[] {"Raigad", "Torna", "Raigad", "Raigad", "Torna"}) {  // loops over every element of new String[] {"Raigad", "Torn...
            int hours = cache.computeIfAbsent(fort, HashMapCacheDemo::slowTrekHours);  // stores the result: computes the value for the key
            System.out.println(fort + " -> " + hours);  // prints the result
        }
        System.out.println("Expensive calculations performed: " + calculations);  // only 2 for 5 requests
    }
}
// OUTPUT:
// Raigad -> 6
// Torna -> 5
// Raigad -> 6
// Raigad -> 6
// Torna -> 5
// Expensive calculations performed: 2

// LinkedHashMap keeps insertion order; HashMap does not
