        Map<String, Integer> plain = new HashMap<>();         // creates an empty HashMap named plain

        String[] forts = {"Torna", "Raigad", "Sinhagad", "Purandar", "Lohagad"};  // stores the value in forts
        int hours = 1;                                   // declares int hours with value 1
        for (String fort : forts) {                      // loops over every element of forts
