// LinkedHashMap with merge() and computeIfAbsent(): groups appear in first-seen order
import java.util.ArrayList;      // imports the ArrayList class
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.List;           // imports the List class
import java.util.Map;            // imports the Map class

public class LinkedHashMapComputeDemo {                       // class that holds the main method
    public static void main(String[] args) {                  // program entry point
        Map<String, Integer> counts = new LinkedHashMap<>();  // creates an empty LinkedHashMap named counts
        for (String city : new String[] {"Nashik", "Pune", "Nashik", "Nagpur", "Pune", "Nashik"}) {  // loops over every element of new String[] {"Nashik", "Pune...
            counts.merge(city, 1, Integer::sum);              // combines the old and new value for the key
        }
        System.out.println("Counts : " + counts);             // prints a label followed by the value

        Map<Integer, List<String>> byLength = new LinkedHashMap<>();  // creates an empty LinkedHashMap named byLength
        for (String fort : new String[] {"Torna", "Raigad", "Lohagad", "Rajgad", "Panhala"}) {  // loops over every element of new String[] {"Torna", "Raiga...
            byLength.computeIfAbsent(fort.length(), k -> new ArrayList<>()).add(fort);  // computes the value for the key
        }
        System.out.println("By length: " + byLength);  // prints a label followed by the value
    }
}
