// LinkedHashMap in access order: reading a key moves it to the end
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.Map;            // imports the Map class

public class LinkedHashMapAccessOrderDemo {            // class that holds the main method
    public static void main(String[] args) {           // program entry point
        Map<String, Integer> recent = new LinkedHashMap<>(16, 0.75f, true);  // true = access order
        recent.put("Raigad", 1);                       // maps key "Raigad" to value 1
        recent.put("Torna", 2);                        // maps key "Torna" to value 2
        recent.put("Purandar", 3);                     // maps key "Purandar" to value 3
        System.out.println("Start      : " + recent);  // prints a label followed by the value

        recent.get("Raigad");                          // Raigad was just used: it moves to the end
        System.out.println("After get  : " + recent);  // prints a label followed by the value

        recent.put("Torna", 22);                       // updating counts as access too
        System.out.println("After put  : " + recent);  // prints a label followed by the value

        recent.containsKey("Purandar");                // does NOT count as access
        System.out.println("containsKey: " + recent);  // prints a label followed by the value
    }
}
// OUTPUT:
// Start      : {Raigad=1, Torna=2, Purandar=3}
// After get  : {Torna=2, Purandar=3, Raigad=1}
// After put  : {Purandar=3, Raigad=1, Torna=22}
// containsKey: {Purandar=3, Raigad=1, Torna=22}

// LRU cache: LinkedHashMap with access order + removeEldestEntry
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.Map;            // imports the Map class

public class LinkedHashMapLruDemo {                            // class that holds the main method
    static class LruCache<K, V> extends LinkedHashMap<K, V> {  // LruCache class extending LinkedHashMap<K, V>
        private final int capacity;                            // field capacity of type int

        LruCache(int capacity) {       // constructor
            super(16, 0.75f, true);    // access order
            this.capacity = capacity;  // stores capacity in the field capacity
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {  // method removeEldestEntry()
            return size() > capacity;  // too many: drop the least recently used
        }
    }

    public static void main(String[] args) {                  // program entry point
        LruCache<String, Integer> cache = new LruCache<>(3);  // creates a LruCache object named cache
        cache.put("Raigad", 1);                               // maps key "Raigad" to value 1
        cache.put("Torna", 2);                                // maps key "Torna" to value 2
        cache.put("Purandar", 3);                             // maps key "Purandar" to value 3
        System.out.println("Full cache      : " + cache);     // prints a label followed by the value

        cache.get("Raigad");                               // Raigad becomes the most recently used
        cache.put("Lohagad", 4);                           // over capacity: Torna (the least recently used) is evicted
        System.out.println("After adding L. : " + cache);  // prints a label followed by the value

        cache.put("Panhala", 5);                           // evicts Purandar
        System.out.println("After adding P. : " + cache);  // prints a label followed by the value
    }
}
// OUTPUT:
// Full cache      : {Raigad=1, Torna=2, Purandar=3}
// After adding L. : {Purandar=3, Raigad=1, Lohagad=4}
// After adding P. : {Raigad=1, Lohagad=4, Panhala=5}

