// In access order, get() inside a loop over the same map fails; loop over a copy instead
import java.util.ArrayList;      // imports the ArrayList class
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.Map;            // imports the Map class

public class LinkedHashMapAccessTrapDemo {    // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Map<String, Integer> cache = new LinkedHashMap<>(16, 0.75f, true);  // creates a LinkedHashMap named cache copied from 16, 0.75f, true
        cache.put("Raigad", 1);               // maps key "Raigad" to value 1
        cache.put("Torna", 2);                // maps key "Torna" to value 2
        cache.put("Purandar", 3);             // maps key "Purandar" to value 3

        try {                                    // code that may throw an exception
            for (String key : cache.keySet()) {  // loops over every element of cache.keySet()
                cache.get(key);                  // each get() re-links the entry
            }
        } catch (java.util.ConcurrentModificationException e) {  // handles java.util.ConcurrentModificationException
            System.out.println("get() inside the loop: ConcurrentModificationException");  // prints the text "get() inside the loop: Conc..."
        }

        for (String key : new ArrayList<>(cache.keySet())) {  // loop over a copy of the keys
            cache.get(key);                                   // reads the value stored for key key
        }
        System.out.println("Looping over a copy works: " + cache);  // prints a label followed by the value
    }
}
// OUTPUT:
// get() inside the loop: ConcurrentModificationException
// Looping over a copy works: {Torna=2, Purandar=3, Raigad=1}

// A report whose fields keep the order in which they were added
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.Map;            // imports the Map class

public class LinkedHashMapReportDemo {                       // class that holds the main method
    public static void main(String[] args) {                 // program entry point
        Map<String, Object> report = new LinkedHashMap<>();  // creates an empty LinkedHashMap named report
        report.put("fort", "Sinhagad");                      // maps key "fort" to value "Sinhagad"
        report.put("city", "Pune");                          // maps key "city" to value "Pune"
        report.put("trekHours", 2);                          // maps key "trekHours" to value 2
        report.put("openAllYear", true);                     // maps key "openAllYear" to value true

        StringBuilder json = new StringBuilder("{");  // creates a StringBuilder object named json
        boolean first = true;                         // declares boolean first with value true
        for (Map.Entry<String, Object> field : report.entrySet()) {  // loops over every element of report.entrySet()
            if (!first) {                             // checks the condition
                json.append(", ");                    // calls append() on json
            }
            first = false;                            // assigns a new value to first
            Object value = field.getValue();          // stores the value in value
            json.append('"').append(field.getKey()).append("\": ");  // calls append() on json
            json.append(value instanceof String ? "\"" + value + "\"" : value);  // calls append() on json
        }
        json.append("}");                             // calls append() on json
        System.out.println(json);                     // prints json
    }
}
// OUTPUT:
// {"fort": "Sinhagad", "city": "Pune", "trekHours": 2, "openAllYear": true}

