import java.util.TreeMap;    // imports the TreeMap class

public class TreeMapMergeDemo {                             // class that holds the main method
    public static void main(String[] args) {                // program entry point
        TreeMap<String, Integer> visits = new TreeMap<>();  // creates an empty TreeMap named visits
        for (String city : new String[] {"Pune", "Nashik", "Pune", "Nagpur", "Pune", "Nashik"}) {  // loops over every element of new String[] {"Pune", "Nashik...
            visits.merge(city, 1, Integer::sum);            // combines the old and new value for the key
        }
        System.out.println("Visits by city : " + visits);   // prints a label followed by the value

        TreeMap<Integer, List<String>> byLength = new TreeMap<>();  // creates an empty TreeMap named byLength
        for (String fort : new String[] {"Torna", "Raigad", "Lohagad", "Rajgad", "Panhala"}) {  // loops over every element of new String[] {"Torna", "Raiga...
            byLength.computeIfAbsent(fort.length(), k -> new ArrayList<>()).add(fort);  // computes the value for the key
        }
        System.out.println("Forts by length: " + byLength);  // prints a label followed by the value
    }
}
