// TreeMap comparator() / clone / equals
import java.util.Comparator;  // imports the Comparator class
import java.util.HashMap;     // imports the HashMap class
import java.util.Map;         // imports the Map class
import java.util.TreeMap;     // imports the TreeMap class

public class TreeMapComparatorDemo {          // class that holds the main method
    public static void main(String[] args) {  // program entry point
        TreeMap<String, Integer> natural = new TreeMap<>(Map.of("Raigad", 6, "Torna", 5));  // creates a TreeMap named natural copied from Map.of("Raigad", 6, "Torn...
        TreeMap<String, Integer> reverse = new TreeMap<>(Comparator.reverseOrder());  // creates a TreeMap ordered by the given comparator
        reverse.putAll(natural);              // copies every entry of natural into the map

        System.out.println("natural.comparator() : " + natural.comparator());  // prints a label followed by the value
        System.out.println("reverse.comparator() is set: " + (reverse.comparator() != null));  // prints a label followed by the value
        System.out.println("natural : " + natural + "   reverse : " + reverse);  // prints a label followed by the value
        System.out.println("equal?  : " + natural.equals(reverse));  // same pairs, so equal

        Map<String, Integer> hash = new HashMap<>(natural);  // creates a HashMap named hash copied from natural
        System.out.println("equals a HashMap with the same pairs: " + natural.equals(hash));  // prints the comparison result

        @SuppressWarnings("unchecked")
        TreeMap<String, Integer> copy = (TreeMap<String, Integer>) reverse.clone();  // stores the result: creates a shallow copy
        copy.put("Lohagad", 2);  // maps key "Lohagad" to value 2
        System.out.println("clone keeps the comparator: " + copy);  // prints a label followed by the value
    }
}
// OUTPUT:
// natural.comparator() : null
// reverse.comparator() is set: true
// natural : {Raigad=6, Torna=5}   reverse : {Torna=5, Raigad=6}
// equal?  : true
// equals a HashMap with the same pairs: true
// clone keeps the comparator: {Torna=5, Raigad=6, Lohagad=2}

// A comparator that ignores part of the key silently merges entries
import java.util.Comparator;  // imports the Comparator class
import java.util.TreeMap;     // imports the TreeMap class

public class TreeMapComparatorTrapDemo {      // class that holds the main method
    public static void main(String[] args) {  // program entry point
        TreeMap<String, Integer> lossy = new TreeMap<>(Comparator.comparing(String::length));  // length only
        lossy.put("Torna", 5);                // maps key "Torna" to value 5
        lossy.put("Lohag", 99);               // same length -> "same key": value replaced
        lossy.put("Raigad", 6);               // maps key "Raigad" to value 6
        System.out.println("Length only      : " + lossy + " (3 puts, " + lossy.size() + " entries)");  // prints the number of elements

        TreeMap<String, Integer> safe = new TreeMap<>(Comparator.comparing(String::length).thenComparing(Comparator.naturalOrder()));  // creates a TreeMap ordered by the given comparator
        safe.put("Torna", 5);   // maps key "Torna" to value 5
        safe.put("Lohag", 99);  // maps key "Lohag" to value 99
        safe.put("Raigad", 6);  // maps key "Raigad" to value 6
        System.out.println("With tie-breaker : " + safe + " (" + safe.size() + " entries)");  // prints the number of elements
    }
}
// OUTPUT:
// Length only      : {Torna=99, Raigad=6} (3 puts, 2 entries)
// With tie-breaker : {Lohag=99, Torna=5, Raigad=6} (3 entries)

