// Two synchronized calls in a row are still a race; one atomic call is safe
import java.util.Hashtable;  // imports the Hashtable class

public class HashtableRaceDemo {                              // class that holds the main method
    public static void main(String[] args) throws InterruptedException {  // program entry point
        Hashtable<String, Integer> racy = new Hashtable<>();  // creates an empty Hashtable named racy
        Hashtable<String, Integer> safe = new Hashtable<>();  // creates an empty Hashtable named safe
        racy.put("Pune", 0);                                  // maps key "Pune" to value 0
        safe.put("Pune", 0);                                  // maps key "Pune" to value 0

        Runnable unsafeTask = () -> {                    // defines unsafeTask as a lambda
            for (int i = 0; i < 20000; i++) {            // counting loop
                racy.put("Pune", racy.get("Pune") + 1);  // get then put: not atomic
            }
        };
        Runnable safeTask = () -> {                      // defines safeTask as a lambda
            for (int i = 0; i < 20000; i++) {            // counting loop
                safe.merge("Pune", 1, Integer::sum);     // one atomic step
            }
        };
        Thread a = new Thread(unsafeTask), b = new Thread(unsafeTask);  // creates a thread named a
        Thread c = new Thread(safeTask), d = new Thread(safeTask);  // creates a thread named c
        a.start();                                       // starts the thread
        b.start();                                       // starts the thread
        c.start();                                       // starts the thread
        d.start();                                       // starts the thread
        a.join();                                        // waits for the thread to finish
        b.join();                                        // waits for the thread to finish
        c.join();                                        // waits for the thread to finish
        d.join();                                        // waits for the thread to finish

        System.out.println("Expected 40000");  // prints the text "Expected 40000"
        System.out.println("safe (merge) : " + safe.get("Pune"));  // prints the element or value read
        System.out.println("racy lost updates: " + (racy.get("Pune") < 40000));  // prints the element or value read
    }
}
// OUTPUT:
// Expected 40000
// safe (merge) : 40000
// racy lost updates: true

