// TreeSet and TreeMap order a Comparable class automatically
import java.util.TreeMap;  // imports the TreeMap class
import java.util.TreeSet;  // imports the TreeSet class

public class ComparableCollectionsDemo {             // class that holds the main method
    static class Fort implements Comparable<Fort> {  // Fort class implementing Comparable<Fort>
        final String name;                           // declares name of type String

        Fort(String name) {    // constructor
            this.name = name;  // stores name in the field name
        }

        @Override
        public int compareTo(Fort other) {      // natural ordering: negative, zero or positive
            return name.compareTo(other.name);  // returns the comparison result
        }

        @Override
        public String toString() {  // text shown when the object is printed
            return name;            // returns the result to the caller
        }
    }

    public static void main(String[] args) {       // program entry point
        TreeSet<Fort> forts = new TreeSet<>();     // creates an empty TreeSet named forts
        forts.add(new Fort("Torna"));              // adds new Fort("Torna") to the set (a duplicate is ignored)
        forts.add(new Fort("Raigad"));             // adds new Fort("Raigad") to the set (a duplicate is ignored)
        forts.add(new Fort("Lohagad"));            // adds new Fort("Lohagad") to the set (a duplicate is ignored)
        forts.add(new Fort("Raigad"));             // compareTo == 0: treated as a duplicate
        System.out.println("TreeSet : " + forts);  // prints a label followed by the value

        TreeMap<Fort, Integer> hours = new TreeMap<>();  // creates an empty TreeMap named hours
        hours.put(new Fort("Torna"), 5);                 // maps key new Fort("Torna") to value 5
        hours.put(new Fort("Lohagad"), 2);               // maps key new Fort("Lohagad") to value 2
        System.out.println("TreeMap : " + hours);        // prints a label followed by the value
    }
}
// OUTPUT:
// TreeSet : [Lohagad, Raigad, Torna]
// TreeMap : {Lohagad=2, Torna=5}

// compareTo using a number field: highest fort first
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class

public class ComparableNumberDemo {                  // class that holds the main method
    static class Fort implements Comparable<Fort> {  // Fort class implementing Comparable<Fort>
        final String name;                           // declares name of type String
        final int heightMetres;                      // declares heightMetres of type int

        Fort(String name, int heightMetres) {  // constructor
            this.name = name;                  // stores name in the field name
            this.heightMetres = heightMetres;  // stores heightMetres in the field heightMetres
        }

        @Override
        public int compareTo(Fort other) {  // natural ordering: negative, zero or positive
            return Integer.compare(other.heightMetres, this.heightMetres);  // swapped: descending
        }

        @Override
        public String toString() {                    // text shown when the object is printed
            return name + "(" + heightMetres + "m)";  // returns the result to the caller
        }
    }

    public static void main(String[] args) {            // program entry point
        List<Fort> forts = new ArrayList<>(List.of(new Fort("Raigad", 820), new Fort("Torna", 1403), new Fort("Lohagad", 1033)));  // creates an ArrayList filled with the listed values
        Collections.sort(forts);                        // sorts the list (natural order or the given comparator)
        System.out.println("Highest first: " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// Highest first: [Torna(1403m), Lohagad(1033m), Raigad(820m)]

// compareTo with a tie-breaker: district first, then name
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class

public class ComparableTieBreakDemo {                // class that holds the main method
    static class Fort implements Comparable<Fort> {  // Fort class implementing Comparable<Fort>
        final String district;                       // declares district of type String
        final String name;                           // declares name of type String

        Fort(String district, String name) {  // constructor
            this.district = district;         // stores district in the field district
            this.name = name;                 // stores name in the field name
        }

        @Override
        public int compareTo(Fort other) {      // natural ordering: negative, zero or positive
            int byDistrict = district.compareTo(other.district);  // declares int byDistrict with value district.compareTo(...
            if (byDistrict != 0) {              // checks the condition
                return byDistrict;              // districts differ: decided
            }
            return name.compareTo(other.name);  // same district: compare names
        }

        @Override
        public String toString() {         // text shown when the object is printed
            return district + "/" + name;  // returns the result to the caller
        }
    }

    public static void main(String[] args) {  // program entry point
        List<Fort> forts = new ArrayList<>(List.of(
                new Fort("Pune", "Torna"), new Fort("Raigad", "Raigad"), new Fort("Pune", "Purandar"), new Fort("Pune", "Lohagad")));
        Collections.sort(forts);              // sorts the list (natural order or the given comparator)
        System.out.println(forts);            // prints forts
    }
}
// OUTPUT:
// [Pune/Lohagad, Pune/Purandar, Pune/Torna, Raigad/Raigad]

// compareTo compares height only; equals compares name: TreeSet and HashSet disagree
import java.util.HashSet;  // imports the HashSet class
import java.util.Objects;  // imports the Objects class
import java.util.Set;      // imports the Set class
import java.util.TreeSet;  // imports the TreeSet class

public class ComparableEqualsTrapDemo {              // class that holds the main method
    static class Fort implements Comparable<Fort> {  // Fort class implementing Comparable<Fort>
        final String name;                           // declares name of type String
        final int heightMetres;                      // declares heightMetres of type int

        Fort(String name, int heightMetres) {  // constructor
            this.name = name;                  // stores name in the field name
            this.heightMetres = heightMetres;  // stores heightMetres in the field heightMetres
        }

        @Override
        public int compareTo(Fort other) {  // natural ordering: negative, zero or positive
            return Integer.compare(heightMetres, other.heightMetres);  // height only
        }

        @Override
        public boolean equals(Object o) {                       // decides when two objects are equal
            return o instanceof Fort f && f.name.equals(name);  // name only
        }

        @Override
        public int hashCode() {         // hash code consistent with equals()
            return Objects.hash(name);  // returns the result to the caller
        }

        @Override
        public String toString() {  // text shown when the object is printed
            return name;            // returns the result to the caller
        }
    }

    public static void main(String[] args) {         // program entry point
        Fort torna = new Fort("Torna", 1403);        // creates a Fort object named torna
        Fort sinhagad = new Fort("Sinhagad", 1403);  // same height, different name

        Set<Fort> tree = new TreeSet<>(Set.of(torna));  // creates a TreeSet filled with the listed values
        tree.add(sinhagad);                             // compareTo == 0: dropped
        Set<Fort> hash = new HashSet<>(Set.of(torna));  // creates a HashSet filled with the listed values
        hash.add(sinhagad);                             // equals false: kept

        System.out.println("TreeSet size : " + tree.size());  // prints the number of elements
        System.out.println("HashSet size : " + hash.size());  // prints the number of elements
    }
}
// OUTPUT:
// TreeSet size : 1
// HashSet size : 2

// compareTo with subtraction gives the wrong sign for large values
public class ComparableOverflowDemo {         // class that holds the main method
    public static void main(String[] args) {  // program entry point
        int small = Integer.MIN_VALUE;        // a very negative number
        int big = 1_000_000_000;              // declares int big with value 1_000_000_000

        int wrong = big - small;                  // overflows to a negative number
        int right = Integer.compare(big, small);  // declares int right with value Integer.compare(big...

        System.out.println("big - small          : " + wrong + "  (says big is smaller: WRONG)");  // prints a label followed by the value
        System.out.println("Integer.compare(...) : " + right + "  (big is larger: correct)");  // prints the comparison result
    }
}
// OUTPUT:
// big - small          : -1147483648  (says big is smaller: WRONG)
// Integer.compare(...) : 1  (big is larger: correct)

