// One order (by name), written three ways
import java.util.ArrayList;   // imports the ArrayList class
import java.util.Comparator;  // imports the Comparator class
import java.util.List;        // imports the List class

public class ComparatorFirstDemo {  // class that holds the main method
    record Fort(String name, String district, int heightMetres, int trekHours) { }

    static List<Fort> sample() {  // method sample()
        return new ArrayList<>(List.of(
                new Fort("Torna", "Pune", 1403, 5),
                new Fort("Raigad", "Raigad", 820, 6),
                new Fort("Lohagad", "Pune", 1033, 2),
                new Fort("Panhala", "Kolhapur", 845, 1),
                new Fort("Purandar", "Pune", 1374, 3)));
    }

    public static void main(String[] args) {          // program entry point
        List<Fort> a = sample();                      // stores the value in a
        a.sort(new Comparator<Fort>() {               // 1. anonymous class
            @Override
            public int compare(Fort x, Fort y) {      // custom ordering of two objects
                return x.name().compareTo(y.name());  // returns the comparison result
            }
        });

        List<Fort> b = sample();                         // stores the value in b
        b.sort((x, y) -> x.name().compareTo(y.name()));  // 2. lambda

        List<Fort> c = sample();                   // stores the value in c
        c.sort(Comparator.comparing(Fort::name));  // 3. helper method

        System.out.println("Same result: " + (a.equals(b) && b.equals(c)));  // prints the comparison result
        c.forEach(f -> System.out.println(f.name()));  // runs the given action for every element
    }
}
// OUTPUT:
// Same result: true
// Lohagad
// Panhala
// Purandar
// Raigad
// Torna

