// comparing(key, keyComparator): case-insensitive name order
import java.util.ArrayList;   // imports the ArrayList class
import java.util.Comparator;  // imports the Comparator class
import java.util.List;        // imports the List class

public class ComparatorKeyComparatorDemo {    // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = new ArrayList<>(List.of("torna", "Raigad", "lohagad", "Panhala"));  // creates an ArrayList filled with the listed values

        forts.sort(Comparator.naturalOrder());  // sorts using the given comparator
        System.out.println("natural (capitals first) : " + forts);  // prints a label followed by the value

        forts.sort(String.CASE_INSENSITIVE_ORDER);  // sorts using the given comparator
        System.out.println("ignore case              : " + forts);  // prints a label followed by the value

        forts.sort(Comparator.comparing(String::length, Comparator.reverseOrder()));  // sorts using the given comparator
        System.out.println("longest name first       : " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// natural (capitals first) : [Panhala, Raigad, lohagad, torna]
// ignore case              : [lohagad, Panhala, Raigad, torna]
// longest name first       : [lohagad, Panhala, Raigad, torna]

// nullsFirst / nullsLast: sorting data that has missing values
import java.util.ArrayList;   // imports the ArrayList class
import java.util.Comparator;  // imports the Comparator class
import java.util.List;        // imports the List class

public class ComparatorNullsDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> districts = new ArrayList<>(List.of("Pune", "Raigad"));  // creates an ArrayList filled with the listed values
        districts.add(null);                  // adds null to the end of the list
        districts.add("Kolhapur");            // adds "Kolhapur" to the end of the list

        districts.sort(Comparator.nullsFirst(Comparator.naturalOrder()));  // sorts using the given comparator
        System.out.println("nulls first : " + districts);  // prints a label followed by the value

        districts.sort(Comparator.nullsLast(Comparator.naturalOrder()));  // sorts using the given comparator
        System.out.println("nulls last  : " + districts);  // prints a label followed by the value
    }
}
// OUTPUT:
// nulls first : [null, Kolhapur, Pune, Raigad]
// nulls last  : [Kolhapur, Pune, Raigad, null]

// One comparator used by TreeSet, PriorityQueue, stream and max/min
import java.util.ArrayList;      // imports the ArrayList class
import java.util.Collections;    // imports the Collections class
import java.util.Comparator;     // imports the Comparator class
import java.util.List;           // imports the List class
import java.util.PriorityQueue;  // imports the PriorityQueue class
import java.util.TreeSet;        // imports the TreeSet class

public class ComparatorWhereDemo {  // class that holds the main method
    record Fort(String name, String district, int heightMetres, int trekHours) { }

    static List<Fort> sample() {  // method sample()
        return new ArrayList<>(List.of(
                new Fort("Torna", "Pune", 1403, 5),
                new Fort("Raigad", "Raigad", 820, 6),
                new Fort("Lohagad", "Pune", 1033, 2),
                new Fort("Panhala", "Kolhapur", 845, 1),
                new Fort("Purandar", "Pune", 1374, 3)));
    }

    public static void main(String[] args) {  // program entry point
        Comparator<Fort> byHeight = Comparator.comparingInt(Fort::heightMetres);  // stores the value in byHeight

        TreeSet<Fort> tree = new TreeSet<>(byHeight.thenComparing(Fort::name));  // creates a TreeSet ordered by the given comparator
        tree.addAll(sample());  // adds every element of sample() to the set
        System.out.println("TreeSet first : " + tree.first().name());  // prints the element or value read

        PriorityQueue<Fort> queue = new PriorityQueue<>(byHeight);  // creates a PriorityQueue named queue copied from byHeight
        queue.addAll(sample());  // adds every element of sample() to the queue
        System.out.println("Queue lowest  : " + queue.poll().name());  // prints the removed element

        List<String> sorted = sample().stream().sorted(byHeight.reversed()).map(Fort::name).toList();  // stores the value in sorted
        System.out.println("Stream, tall first : " + sorted);  // prints a label followed by the value

        System.out.println("max / min     : " + Collections.max(sample(), byHeight).name() + " / " + Collections.min(sample(), byHeight).name());  // prints a label followed by the value
    }
}
// OUTPUT:
// TreeSet first : Raigad
// Queue lowest  : Raigad
// Stream, tall first : [Torna, Purandar, Lohagad, Panhala, Raigad]
// max / min     : Torna / Raigad

