// reversed() reverses everything before it
import java.util.ArrayList;   // imports the ArrayList class
import java.util.Comparator;  // imports the Comparator class
import java.util.List;        // imports the List class

public class ComparatorReversedTrapDemo {  // class that holds the main method
    record Fort(String name, String district, int heightMetres, int trekHours) { }

    static List<Fort> sample() {  // method sample()
        return new ArrayList<>(List.of(
                new Fort("Torna", "Pune", 1403, 5),
                new Fort("Raigad", "Raigad", 820, 6),
                new Fort("Lohagad", "Pune", 1033, 2),
                new Fort("Panhala", "Kolhapur", 845, 1),
                new Fort("Purandar", "Pune", 1374, 3)));
    }

    public static void main(String[] args) {  // program entry point
        // Wanted: district A to Z, tallest first inside each district
        Comparator<Fort> wrong = Comparator.comparing(Fort::district).thenComparingInt(Fort::heightMetres).reversed();  // stores the value in wrong
        Comparator<Fort> right = Comparator.comparing(Fort::district).thenComparing(Comparator.comparingInt(Fort::heightMetres).reversed());  // stores the value in right

        List<Fort> a = sample();                                // stores the value in a
        a.sort(wrong);                                          // sorts using the given comparator
        System.out.print("wrong (districts also reversed): ");  // prints the text "wrong (districts also rever..."
        a.forEach(f -> System.out.print(f.district() + ":" + f.name() + " "));  // runs the given action for every element

        List<Fort> b = sample();  // stores the value in b
        b.sort(right);            // sorts using the given comparator
        System.out.print("\nright                          : ");  // prints the text "\nright..."
        b.forEach(f -> System.out.print(f.district() + ":" + f.name() + " "));  // runs the given action for every element
        System.out.println();     // prints an empty line
    }
}
// OUTPUT:
// wrong (districts also reversed): Raigad:Raigad Pune:Torna Pune:Purandar Pune:Lohagad Kolhapur:Panhala
// right                          : Kolhapur:Panhala Pune:Torna Pune:Purandar Pune:Lohagad Raigad:Raigad

// A TreeSet comparator on one field silently drops forts that tie
import java.util.ArrayList;   // imports the ArrayList class
import java.util.Comparator;  // imports the Comparator class
import java.util.List;        // imports the List class
import java.util.TreeSet;     // imports the TreeSet class

public class ComparatorTreeSetTrapDemo {  // class that holds the main method
    record Fort(String name, String district, int heightMetres, int trekHours) { }

    static List<Fort> sample() {  // method sample()
        return new ArrayList<>(List.of(
                new Fort("Torna", "Pune", 1403, 5),
                new Fort("Raigad", "Raigad", 820, 6),
                new Fort("Lohagad", "Pune", 1033, 2),
                new Fort("Panhala", "Kolhapur", 845, 1),
                new Fort("Purandar", "Pune", 1374, 3)));
    }

