// MiniHashSet: the real design of java.util.HashSet in about 20 lines
import java.util.HashMap;  // imports the HashMap class

public class MiniHashSetDemo {                               // class that holds the main method
    static class MiniHashSet<E> {                            // declares the MiniHashSet class
        private static final Object PRESENT = new Object();  // shared dummy value
        private final HashMap<E, Object> map = new HashMap<>();  // creates an empty HashMap named map

        boolean add(E e) {                       // method add()
            return map.put(e, PRESENT) == null;  // true if the key was new
        }

        boolean contains(Object o) {    // method contains()
            return map.containsKey(o);  // returns the result to the caller
        }

        boolean remove(Object o) {            // method remove()
            return map.remove(o) == PRESENT;  // returns the result to the caller
        }

        int size() {            // method size()
            return map.size();  // returns the result to the caller
        }

        @Override
        public String toString() {           // text shown when the object is printed
            return map.keySet().toString();  // the elements are the keys
        }
    }

    public static void main(String[] args) {              // program entry point
        MiniHashSet<String> forts = new MiniHashSet<>();  // creates an empty MiniHashSet named forts
        System.out.println("add Raigad  : " + forts.add("Raigad"));  // prints the result of the add
        System.out.println("add Torna   : " + forts.add("Torna"));  // prints the result of the add
