        System.out.println("contains Torna : " + forts.contains("Torna"));  // prints whether the element is present
        System.out.println("remove Torna   : " + forts.remove("Torna"));  // prints the removed element
        System.out.println("remove Torna   : " + forts.remove("Torna"));  // prints the removed element
        System.out.println("Set: " + forts + ", size " + forts.size());  // prints the number of elements
    }
}
