// One null is allowed; changing the set inside a for-each is not
import java.util.HashSet;   // imports the HashSet class
import java.util.Iterator;  // imports the Iterator class
import java.util.Set;       // imports the Set class

public class SetNullFailFastDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Set<String> forts = new HashSet<>();  // creates an empty HashSet named forts
        forts.add("Raigad");                  // adds "Raigad" to the set (a duplicate is ignored)
        forts.add(null);                      // adds null to the set (a duplicate is ignored)
        forts.add(null);                      // still one null
        System.out.println("size with null : " + forts.size());  // prints the number of elements
        forts.remove(null);                   // removes null from the set

        forts.addAll(java.util.List.of("Torna", "Lohagad", "Panhala"));  // adds every element of java.util.List.of("Torna", "Lohag... to the set
        try {                         // code that may throw an exception
            for (String f : forts) {  // loops over every element of forts
                forts.remove(f);      // structural change inside the loop
            }
        } catch (java.util.ConcurrentModificationException e) {  // handles java.util.ConcurrentModificationException
            System.out.println("remove in for-each -> ConcurrentModificationException");  // prints the text "remove in for-each -> Concu..."
        }

        Iterator<String> it = forts.iterator();  // stores the result: gets an iterator to walk the elements
        while (it.hasNext()) {                   // runs while the iterator has more elements
            if (it.next().startsWith("P")) {     // checks the condition
                it.remove();                     // the safe way
            }
        }
        forts.removeIf(f -> f.length() > 6);     // removes every element that matches the condition
        System.out.println("after safe removal: " + new java.util.TreeSet<>(forts));  // prints a label followed by the value
    }
}
// OUTPUT:
// size with null : 2
// remove in for-each -> ConcurrentModificationException
// after safe removal: [Raigad, Torna]

// The cost of a HashSet: a node per element; compare with a BitSet for small ints
import java.util.BitSet;   // imports the BitSet class
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class

public class SetMemoryDemo {                  // class that holds the main method
    public static void main(String[] args) {  // program entry point
        int n = 100_000;                      // declares int n with value 100_000
        Set<Integer> set = new HashSet<>();   // creates an empty HashSet named set
        BitSet bits = new BitSet();           // creates an empty BitSet named bits
        for (int i = 0; i < n; i += 2) {      // counting loop
            set.add(i);                       // adds i to the set (a duplicate is ignored)
            bits.set(i);                      // calls set() on bits
        }
        System.out.println("HashSet contains 1000 : " + set.contains(1000) + ", 1001 : " + set.contains(1001));  // prints whether the element is present
        System.out.println("BitSet  contains 1000 : " + bits.get(1000) + ", 1001 : " + bits.get(1001));  // prints the element or value read
        System.out.println("BitSet size in bytes ~ " + bits.size() / 8 + " for " + bits.cardinality() + " numbers");  // prints the number of elements
        System.out.println("HashSet needs one Node object (about 32 bytes) per number, so ~" + set.size() * 32 / 1024 + " KB before the table");  // prints the number of elements
    }
}
// OUTPUT:
// HashSet contains 1000 : true, 1001 : false
// BitSet  contains 1000 : true, 1001 : false
// BitSet size in bytes ~ 16384 for 50000 numbers
// HashSet needs one Node object (about 32 bytes) per number, so ~1562 KB before the table

