// Step 1 and 2 by hand: from a key to a bucket number (capacity 16)
public class HashStepsDemo {         // class that holds the main method
    static int spread(Object key) {  // method spread()
        int h = key.hashCode();      // stores the result: computes the hash code
        return h ^ (h >>> 16);       // mix high bits into low bits (same as HashMap.hash)
    }

    public static void main(String[] args) {    // program entry point
        int capacity = 16;                      // declares int capacity with value 16
        for (String fort : new String[] {"Raigad", "Torna", "Lohagad", "Panhala", "Purandar"}) {  // loops over every element of new String[] {"Raigad", "Torn...
            int hash = spread(fort);            // declares int hash with value spread(fort)
            int index = (capacity - 1) & hash;  // (n - 1) & hash: the bucket number
            System.out.println(fort + "  hashCode=" + fort.hashCode() + "  bucket=" + index);  // prints the comparison result
        }
    }
}
// OUTPUT:
// Raigad  hashCode=-1854565232  bucket=5
// Torna  hashCode=80995626  bucket=9
// Lohagad  hashCode=2007676782  bucket=4
// Panhala  hashCode=867660331  bucket=12
