// MiniHashMap: put() and get() with a fixed 4 buckets, to show collisions
public class MiniHashMapDemo {  // class that holds the main method
    static class Node {         // declares the Node class
        final String key;       // declares key of type String
        int value;              // declares value of type int
        Node next;              // declares next of type Node

        Node(String key, int value) {  // constructor
            this.key = key;            // stores key in the field key
            this.value = value;        // stores value in the field value
        }
    }

    static class MiniHashMap {       // declares the MiniHashMap class
        Node[] table = new Node[4];  // the bucket array

        int indexFor(String key) {          // method indexFor()
            int h = key.hashCode();         // stores the result: computes the hash code
            h = h ^ (h >>> 16);             // spread
            return (table.length - 1) & h;  // bucket number
        }

        void put(String key, int value) {       // method put()
            int i = indexFor(key);              // declares int i with value indexFor(key)
            for (Node n = table[i]; n != null; n = n.next) {
                if (n.key.equals(key)) {        // same key: update
                    n.value = value;            // sets the field value of n
                    return;                     // ends the method
                }
            }
            Node fresh = new Node(key, value);  // new key: add at the front of the chain
            fresh.next = table[i];              // sets the field next of fresh
            table[i] = fresh;                   // stores fresh at index i of table
        }

        Integer get(String key) {         // method get()
            for (Node n = table[indexFor(key)]; n != null; n = n.next) {
                if (n.key.equals(key)) {  // checks the condition
                    return n.value;       // returns the result to the caller
                }
            }
            return null;                  // absent
        }

        void print() {                                // method print()
            for (int i = 0; i < table.length; i++) {  // loops through all the indexes
                StringBuilder row = new StringBuilder("bucket " + i + ": ");  // creates a StringBuilder object named row
                for (Node n = table[i]; n != null; n = n.next) {
                    row.append(n.key).append("=").append(n.value).append(" ");  // calls append() on row
                }
                System.out.println(row);              // prints row
            }
        }
    }

    public static void main(String[] args) {  // program entry point
        MiniHashMap map = new MiniHashMap();  // creates an empty MiniHashMap named map
        for (String fort : new String[] {"Raigad", "Torna", "Lohagad", "Panhala", "Purandar", "Sinhagad"}) {  // loops over every element of new String[] {"Raigad", "Torn...
            map.put(fort, fort.length());     // maps key fort to value fort.length()
        }
        map.put("Torna", 99);                 // update, not a new node
        map.print();                          // calls print() on map
        System.out.println("get(Torna)  = " + map.get("Torna"));  // prints the element or value read
        System.out.println("get(Missing)= " + map.get("Missing"));  // prints the element or value read
    }
}
// OUTPUT:
// bucket 0: Panhala=7 Lohagad=7
// bucket 1: Sinhagad=8 Torna=99 Raigad=6
// bucket 2: Purandar=8
// bucket 3:
// get(Torna)  = 99
// get(Missing)= null

