        int threshold = (int) (capacity * loadFactor);  // declares int threshold with value (int) (capacity * l...

        System.out.println("start: capacity=" + capacity + " threshold=" + threshold);  // prints a label followed by the value
        for (int size = 1; size <= 50; size++) {            // counting loop
            if (size > threshold) {                         // the put that crosses the threshold resizes
                capacity = capacity * 2;                    // assigns a new value to capacity
                threshold = (int) (capacity * loadFactor);  // assigns a new value to threshold
                System.out.println("entry #" + size + " -> resize: capacity=" + capacity + " threshold=" + threshold);  // prints a label followed by the value
            }
        }
    }
}
// OUTPUT:
// start: capacity=16 threshold=12
// entry #13 -> resize: capacity=32 threshold=24
// entry #25 -> resize: capacity=64 threshold=48
// entry #49 -> resize: capacity=128 threshold=96

// After doubling 16 -> 32, an entry stays or moves by exactly 16
public class ResizeSplitDemo {       // class that holds the main method
    static int spread(String key) {  // method spread()
        int h = key.hashCode();      // stores the result: computes the hash code
        return h ^ (h >>> 16);       // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        for (String fort : new String[] {"Raigad", "Torna", "Lohagad", "Panhala", "Purandar", "Sinhagad"}) {  // loops over every element of new String[] {"Raigad", "Torn...
            int hash = spread(fort);          // declares int hash with value spread(fort)
            int oldIndex = 15 & hash;         // capacity 16
            int newIndex = 31 & hash;         // capacity 32
            String what = (newIndex == oldIndex) ? "stays" : "moves by " + (newIndex - oldIndex);  // stores the value in what
            System.out.println(fort + ": " + oldIndex + " -> " + newIndex + "  (" + what + ")");  // prints the result
        }
    }
}
// OUTPUT:
// Raigad: 5 -> 5  (stays)
// Torna: 9 -> 25  (moves by 16)
// Lohagad: 4 -> 4  (stays)
// Panhala: 12 -> 28  (moves by 16)
// Purandar: 2 -> 18  (moves by 16)
// Sinhagad: 5 -> 21  (moves by 16)

// Many colliding keys still work: this key class always returns the same hash
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class

public class TreeifyDemo {  // class that holds the main method
    static class SameHashKey implements Comparable<SameHashKey> {  // SameHashKey class implementing Comparable<SameHashKey>
        final int id;       // declares id of type int

        SameHashKey(int id) {  // constructor
            this.id = id;      // stores id in the field id
        }

        @Override
        public int hashCode() {  // hash code consistent with equals()
            return 42;           // every key collides
        }

        @Override
        public boolean equals(Object o) {                     // decides when two objects are equal
            return o instanceof SameHashKey k && k.id == id;  // returns the result to the caller
        }

        @Override
        public int compareTo(SameHashKey other) {  // natural ordering: negative, zero or positive
            return Integer.compare(id, other.id);  // lets the tree order the keys
        }
    }

    public static void main(String[] args) {              // program entry point
        Map<SameHashKey, Integer> map = new HashMap<>();  // creates an empty HashMap named map
        for (int i = 0; i < 1000; i++) {                  // counting loop
            map.put(new SameHashKey(i), i);               // one bucket, turned into a tree
        }
        System.out.println("size      : " + map.size());  // prints the number of elements
        System.out.println("get(777)  : " + map.get(new SameHashKey(777)));  // prints the element or value read
        System.out.println("get(5000) : " + map.get(new SameHashKey(5000)));  // prints the element or value read
    }
}
// OUTPUT:
// size      : 1000
// get(777)  : 777
// get(5000) : null

// Null key lives in bucket 0; iteration order follows the buckets, not insertion
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class

public class NullAndOrderDemo {                      // class that holds the main method
    public static void main(String[] args) {         // program entry point
        Map<String, Integer> map = new HashMap<>();  // creates an empty HashMap named map
        map.put("Torna", 5);                         // maps key "Torna" to value 5
        map.put(null, 0);                            // allowed: hash = 0
        map.put("Raigad", 6);                        // maps key "Raigad" to value 6
        map.put("Lohagad", 2);                       // maps key "Lohagad" to value 2

        System.out.println("Inserted : Torna, null, Raigad, Lohagad");  // prints the text "Inserted : Torna, null, Rai..."
        System.out.println("Iterated : " + map.keySet());   // prints the keys, values or entries
        System.out.println("get(null): " + map.get(null));  // prints the element or value read
    }
}
// OUTPUT:
// Inserted : Torna, null, Raigad, Lohagad
// Iterated : [null, Lohagad, Raigad, Torna]
// get(null): 0

// Without spreading, keys that differ only in high bits collide
public class SpreadDemo {                                     // class that holds the main method
    public static void main(String[] args) {                  // program entry point
        int[] hashes = {0x10000, 0x20000, 0x30000, 0x40000};  // differ only above bit 16
        for (int h : hashes) {                                // loops over every element of hashes
            int plain = 15 & h;                               // declares int plain with value 15 & h
            int spread = 15 & (h ^ (h >>> 16));               // declares int spread with value 15 & (h ^ (h >>> 16...
            System.out.println("hash=" + Integer.toHexString(h) + "  plain bucket=" + plain + "  spread bucket=" + spread);  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// hash=10000  plain bucket=0  spread bucket=1
// hash=20000  plain bucket=0  spread bucket=2
