// hash=40000  plain bucket=0  spread bucket=4

// modCount in action: changing the map during a loop
import java.util.HashMap;   // imports the HashMap class
import java.util.Iterator;  // imports the Iterator class
import java.util.Map;       // imports the Map class

public class FailFastDemo {                   // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Map<String, Integer> map = new HashMap<>(Map.of("Raigad", 6, "Torna", 5, "Lohagad", 2));  // creates a HashMap named map copied from Map.of("Raigad", 6, "Torn...

        for (String fort : map.keySet()) {     // loops over every element of map.keySet()
            map.put(fort, map.get(fort) + 1);  // update existing key: allowed
        }
        System.out.println("After updates: " + new java.util.TreeMap<>(map));  // prints a label followed by the value

        try {                                   // code that may throw an exception
            for (String fort : map.keySet()) {  // loops over every element of map.keySet()
                map.put(fort + "-new", 1);      // new key: structural change (the first put succeeds, the next loop step throws)
            }
        } catch (java.util.ConcurrentModificationException e) {  // handles java.util.ConcurrentModificationException
            System.out.println("Adding keys while looping -> ConcurrentModificationException");  // prints the text "Adding keys while looping -..."
        }

        Iterator<Map.Entry<String, Integer>> it = map.entrySet().iterator();  // stores the result: gets the set of key-value entries
        while (it.hasNext()) {               // runs while the iterator has more elements
            if (it.next().getValue() > 6) {  // checks the condition
                it.remove();                 // safe removal through the iterator
            }
        }
        System.out.println("After iterator.remove: " + new java.util.TreeMap<>(map));  // prints a label followed by the value
    }
}
// OUTPUT:
// After updates: {Lohagad=3, Raigad=7, Torna=6}
// Adding keys while looping -> ConcurrentModificationException
// After iterator.remove: {Lohagad=3, Lohagad-new=1, Torna=6}

// Capacity needed for N entries without a resize: N / 0.75, rounded up to a power of two
public class SizingDemo {               // class that holds the main method
    static int tableSizeFor(int cap) {  // same idea as HashMap.tableSizeFor
        int n = 1;                      // declares int n with value 1
        while (n < cap) {               // repeats while the condition is true
            n <<= 1;
        }
        return n;                       // returns the result to the caller
    }

    public static void main(String[] args) {                // program entry point
        for (int expected : new int[] {5, 12, 13, 100, 1000}) {  // loops over every element of new int[] {5, 12, 13, 100, 10...
            int needed = (int) Math.ceil(expected / 0.75);  // declares int needed with value (int) Math.ceil(exp...
            System.out.println(expected + " entries -> ask for " + needed + " -> table of " + tableSizeFor(needed) + " buckets");  // prints the result
        }
        System.out.println("new HashMap<>(10) really creates a table of " + tableSizeFor(10));  // prints a label followed by the value
    }
}
// OUTPUT:
// 5 entries -> ask for 7 -> table of 8 buckets
// 12 entries -> ask for 16 -> table of 16 buckets
// 13 entries -> ask for 18 -> table of 32 buckets
// 100 entries -> ask for 134 -> table of 256 buckets
// 1000 entries -> ask for 1334 -> table of 2048 buckets
// new HashMap<>(10) really creates a table of 16
